// Üretilen dosya: tool/ozgun/uret.py. Biyoloji ve Yaşam Bilimleri · Evrimsel biyoloji ve popülasyon genetiği: doğal seçilim biçimleri, Hardy-Weinberg dengesi, genetik sürüklenme ve türleşme mekanizmaları (zor).
const ozBiology17Zor = <(String, String, List<String>, String)>[
  ('Otozomal çekinik kalıtılan kistik fibrozis hastalığı, dengedeki bir popülasyonda her 2500 doğumda 1 görülmektedir. Bu popülasyonda sağlıklı görünen taşıyıcı bireylerin tüm popülasyona oranı kesirli olarak yaklaşık kaçtır?', '98 / 2500', ['1 / 50', '49 / 2500', '2401 / 2500'], 'q² = 1/2500 ise q = 1/50 ve p = 49/50 olur. Taşıyıcı (2pq) oranı = 2 × (49/50) × (1/50) = 98/2500\'dür.'),
  ('Dengedeki bir popülasyonda X kromozomuna bağlı çekinik renk körlüğü erkeklerin %8\'inde görülmektedir. Bu popülasyondaki kadınların yüzde kaçının renk körlüğü bakımından taşıyıcı olması beklenir?', '%14,72', ['%0,64', '%16,00', '%92,00'], 'Erkekler tek X taşıdığından hasta erkek oranı doğrudan q = 0,08 değerini verir; p = 0,92 olur. Kadınlarda taşıyıcı oranı 2pq = 2 × 0,92 × 0,08 = 0,1472 yani %14,72\'dir.'),
  ('X\'e bağlı çekinik bir özelliğin Hardy-Weinberg dengesindeki bir popülasyonda erkeklerde görülme sıklığı 1/20\'dir. Aynı özelliğin kadınlarda fenotipte görülme sıklığı kaçtır?', '1 / 400', ['1 / 20', '1 / 40', '19 / 200'], 'Erkeklerde çekinik fenotip sıklığı q = 1/20\'dir. Kadınlarda fenotipte görülmesi için iki çekinik alel (q²) gerektiğinden oran (1/20)² = 1/400 olur.'),
  ('Tam baskınlığın görüldüğü bir karakter ile eş baskınlığın görüldüğü başka bir karakter karşılaştırıldığında, popülasyondaki alel frekanslarının doğrudan fenotip sayımından hesaplanabilmesi açısından hangi çıkarım doğrudur?', 'Eş baskınlıkta denge varsayımına gerek kalmadan alel frekansları doğrudan sayılabilir', ['Tam baskınlıkta heterozigotlar dış görünüşten ayrılabildiği için hesaplama daha kesin yapılır', 'Her iki kalıtım biçiminde de Hardy-Weinberg dengesi olmadan alel frekansı bulunamaz', 'Eş baskınlıkta çekinik fenotip bulunmadığı için p + q = 1 eşitliği kullanılamaz'], 'Eş baskınlık ve eksik baskınlıkta her genotip kendine özgü fenotip oluşturduğundan, popülasyon dengede olmasa bile aleller doğrudan sayılıp frekans bulunabilir.'),
  ('ABO kan grubu sisteminde IA (p), IB (q) ve i (r) olmak üzere üç alel bulunur ve p + q + r = 1\'dir. Dengedeki bir popülasyonda O kan grubu %4, B kan grubu %21 oranında görülüyorsa A alelinin (p) frekansı kaçtır?', '0,5', ['0,3', '0,2', '0,25'], 'O grubu (ii) r² = 0,04 ise r = 0,2\'dir. B grubu + O grubu = (q + r)² = 0,21 + 0,04 = 0,25 olduğundan q + r = 0,5 ve q = 0,3 bulunur. p = 1 - 0,5 = 0,5\'tir.'),
  ('Üç alelli bir gen sisteminde (p + q + r = 1) Hardy-Weinberg dengesindeki bir tavşan popülasyonunda alel frekansları p = 0,5, q = 0,3 ve r = 0,2 olarak verilmiştir. Bu popülasyondaki toplam heterozigot bireylerin oranı kaçtır?', '0,62', ['0,38', '0,31', '0,50'], 'Üç alelli sistemde heterozigotların toplam oranı 2pq + 2pr + 2qr = 2(0,15) + 2(0,10) + 2(0,06) = 0,30 + 0,20 + 0,12 = 0,62\'dir (veya 1 - (p²+q²+r²) = 1 - 0,38 = 0,62).'),
  ('Bir popülasyonda çekinik alel frekansı q = 0,01 gibi çok küçük bir değerdeyken çekinik alellerin büyük çoğunluğu hangi bireylerde bulunur?', 'Fenotipik olarak baskın görünen heterozigot taşıyıcı bireylerde', ['Fenotipinde çekinik özelliği gösteren homozigot bireylerde', 'Yalnızca homozigot baskın genotipli sağlıklı bireylerde', 'Üreme yeteneğini tamamen kaybetmiş mutant bireylerde'], 'q = 0,01 iken q² = 0,0001 ve 2pq = 2 × 0,99 × 0,01 = 0,0198 olur; çekinik alellerin yaklaşık %99\'u heterozigot taşıyıcılarda gizli kalır.'),
  ('Zararlı ve öldürücü otozomal çekinik bir genetik hastalığa karşı güçlü doğal seçilim işlemesine rağmen bu çekinik alelin popülasyondan tamamen yok edilmesinin çok uzun sürmesinin temel nedeni nedir?', 'Alelin heterozigot bireylerde fenotipe yansımadan seçilimden korunması', ['Çekinik alellerin her kuşakta baskın alellere göre daha hızlı kopyalanması', 'Homozigot çekinik bireylerin üreme başarısının ortalamanın üzerinde olması', 'Hardy-Weinberg dengesinin zararlı alellerin frekansını sabit tutması'], 'Doğal seçilim fenotip üzerinden etki eder; heterozigot (Aa) bireyler sağlıklı göründüğü için çekinik aleli seçilim baskısından gizleyerek gelecek nesillere aktarır.'),
  ('Başlangıçta %100 Aa heterozigot bireylerden oluşan ve sadece kendi kendine tozlaşarak üreyen bir bezelye popülasyonunda, seçilim ve mutasyon yoksa 3. dölde (F3) heterozigot bireylerin oranı yüzde kaç olur?', '%12,5', ['%25,0', '%50,0', '%6,25'], 'Tam öz döllenmede her nesilde heterozigotların yalnızca yarısı tekrar heterozigot döl verir: 1. dölde %50, 2. dölde %25, 3. dölde %12,5 olur.'),
  ('Dengedeki bir popülasyonda heterozigot bireylerin frekansı, homozigot çekinik bireylerin frekansının 6 katına eşittir. Buna göre bu popülasyonda homozigot baskın bireylerin yüzdesi kaçtır?', '%56,25', ['%75,00', '%37,50', '%6,25'], '2pq = 6q² eşitliğinden (q ≠ 0 için) 2p = 6q yani p = 3q bulunur. p + q = 1 olduğundan q = 0,25 ve p = 0,75\'tir. Homozigot baskın p² = (0,75)² = 0,5625 yani %56,25 olur.'),
  ('Sıtmanın yaygın olduğu bölgelerde orak hücreli anemi aleli (HbS) bakımından heterozigot (HbA HbS) olan bireyler sıtmaya dirençli iken, homozigot (HbS HbS) bireyler ağır anemi nedeniyle düşük yaşam şansına sahiptir. Bu durum gen havuzunu nasıl etkiler?', 'Heterozigot avantajı sayesinde zararlı çekinik alel popülasyonda yüksek frekansta korunur', ['HbS aleli birkaç kuşak içinde doğal seçilimle gen havuzundan tamamen temizlenir', 'Popülasyondaki tüm bireyler zamanla homozigot normal (HbA HbA) genotipine sabitlenir', 'Hardy-Weinberg dengesi hiç bozulmadan tüm genotipler eşit oranda varlığını sürdürür'], 'Dengeleyici seçilim (heterozigot üstünlüğü), her iki homozigota göre heterozigotları kayırdığı için çekinik hastalık alelinin popülasyonda kalıcı olmasını sağlar.'),
  ('Başlangıçta Hardy-Weinberg dengesinde olmayan büyük bir popülasyonda; mutasyon, seçilim, göç yoksa ve bireyler rastgele eşleşmeye başlarsa otozomal bir lokus kaç nesil sonra dengeye ulaşır?', 'Tek bir rastgele eşleşme neslinin hemen ardından dengeye ulaşır', ['Alel frekansları 0,5 değerinde eşitlenene kadar yüzlerce nesil gerekir', 'Hiçbir zaman dengeye ulaşamaz ve başlangıçtaki genotip oranlarını korur', 'Yalnızca homozigot çekinik bireyler elendikten sonra onuncu nesilde ulaşır'], 'Otozomal tek bir lokusta tüm H-W varsayımları sağlandığında, gametlerin rastgele birleşmesiyle sadece 1 kuşak sonra genotip frekansları p², 2pq ve q² dengesine oturur.'),
  ('X kromozomuna bağlı bir gen lokusunda erkeklerdeki alel frekansı ile kadınlardaki alel frekansı başlangıçta birbirinden farklıysa, rastgele eşleşen büyük bir popülasyonda dengeye ulaşma süreci otozomal genlere göre nasıl farklılık gösterir?', 'Tek nesilde dengeye gelmez; cinsiyetler arası frekans farkı her nesilde azalarak kademeli yaklaşır', ['X\'e bağlı genler erkeklerde tek kopya olduğu için ilk nesilde anında dengeye ulaşır', 'Kadınlardaki alel frekansı sabit kalırken erkeklerdeki frekans hiç değişmeden devam eder', 'Cinsiyete bağlı genlerde Hardy-Weinberg dengesi hiçbir koşulda kurulamaz'], 'Erkekler X kromozomunu yalnızca annelerinden aldığı için, cinsiyetler arasındaki alel frekansı farkı her nesilde yarıya inerek sönümlü salınımla birkaç nesilde dengeye yaklaşır.'),
  ('Bir ada popülasyonunda otozomal bir lokus için yapılan analizde p = 0,7 ve q = 0,3 bulunmuş; ancak gözlenen genotip oranları AA = %60, Aa = %20 ve aa = %20 olarak ölçülmüştür. Beklenen değerlerle kıyaslandığında bu sapmanın olası nedeni aşağıdakilerden hangisi olabilir?', 'Popülasyonda soy içi üreme veya pozitif asortatif eşleşmenin yaygın olması', ['Heterozigot bireylerin her iki homozigota göre yüksek uyum başarısı göstermesi', 'Popülasyonun tüm Hardy-Weinberg varsayımlarını eksiksiz yerine getirmesi', 'Baskın alelin çekinik alel üzerinde eksik baskınlık özelliği göstermesi'], 'Beklenen oranlar AA=%49, Aa=%42, aa=%9 iken gözlenende heterozigotlar azalmış (%20), her iki homozigot artmıştır; bu durum tipik olarak soy içi üreme veya benzerlerin eşleşmesi sonucudur.'),
  ('Dengedeki bir insan popülasyonunda otozomal çekinik albinoluk sıklığı 1/10.000\'dir. Popülasyonda taşıyıcı (heterozigot) birey sıklığının hasta birey sıklığına oranı yaklaşık kaçtır?', '198', ['99', '100', '50'], 'q² = 1/10.000 ise q = 1/100 = 0,01 ve p = 0,99\'dur. Taşıyıcı sıklığı (2pq) / Hasta sıklığı (q²) = 2p / q = (2 × 0,99) / 0,01 = 198 katıdır.'),
  ('Bir popülasyonda otozomal bir genin çekinik aleli embriyonik dönemde %100 öldürücüdür (letal). Başlangıçta çekinik alel frekansı q₀ = 0,25 olan ve rastgele eşleşen büyük bir popülasyonda, tek bir seçilim kuşağı sonrasında yetişkinlerdeki yeni çekinik alel frekansı (q₁) kaç olur?', '0,20', ['0,125', '0,0625', '0,15'], 'Tam resesif letal seçilimde bir kuşak sonraki frekans q₁ = q₀ / (1 + q₀) formülüyle (veya p=0,75, q=0,25 iken p²=9/16, 2pq=6/16 yaşar; 15 birim hayatta kalanda 30 alelin 6\'sı çekiniktir: 6/30 = 0,20) bulunur.'),
  ('Haploid (n kromozomlu) üreyen bir mantar popülasyonunun vejetatif evresinde bir gen lokusu p ve q alellerine sahipse, bu evredeki genotip frekansları aşağıdakilerden hangisiyle ifade edilir?', 'Doğrudan p ve q oranlarıyla ifade edilir', ['p² + 2pq + q² = 1 denklemiyle ifade edilir', 'p³ + 3p²q + 3pq² + q³ = 1 açılımıyla ifade edilir', 'Yalnızca 2pq heterozigot oranıyla ifade edilir'], 'Haploid organizmalar her genden tek bir kopya taşıdığından heterozigotluk görülmez; bireylerin genotip frekansları doğrudan p ve q alel frekanslarına eşittir.'),
  ('Otozomal çekinik bir hastalığın dengedeki bir popülasyonda taşıyıcı sıklığı (2pq), çekinik alel çok nadir olduğu için yaklaşık "2q" olarak kabul edilebilmektedir. Hastalık sıklığı 1/3600 olan bir toplumda bu yaklaşıma göre taşıyıcı sıklığı yaklaşık kaçtır?', '1 / 30', ['1 / 60', '1 / 1800', '1 / 900'], 'q² = 1/3600 olduğundan q = 1/60 bulunur. p ≈ 1 olduğu için taşıyıcı sıklığı 2pq ≈ 2q = 2 × (1/60) = 1/30 olarak yaklaşık ve hızlı biçimde hesaplanır.'),
  ('İki ayrı nehir kolunda yaşayan aynı türe ait alabalık popülasyonlarının her ikisinde de A alelinin frekansı p = 0,6 ve a alelinin frekansı q = 0,4 olarak ölçülmüştür. Bu iki popülasyon için aşağıdakilerden hangisi KESİNLİKLE doğrudur?', 'Alel frekansları aynı olmasına rağmen genotip frekansları birbirinden farklı olabilir', ['Her iki popülasyonda da heterozigot bireylerin oranı kesinlikle %48 olmak zorundadır', 'İki nehir kolundaki toplam balık sayıları birbirine tam olarak eşittir', 'Her iki popülasyon da kesinlikle Hardy-Weinberg dengesinde bulunmaktadır'], 'Popülasyonlardan biri dengede (Aa=%48), diğeri soy içi üreme veya seçilim etkisinde (örneğin Aa=%20, AA=%50, aa=%30) olup yine p=0,6 ve q=0,4 değerine sahip olabilir.'),
  ('Bir laboratuvar deneyinde, AA genotipli 100 dişi meyve sineği ile aa genotipli 100 erkek meyve sineği aynı kafese konulup rastgele eşleşmeye bırakılmıştır (F0 kuşağı). Seçilim ve mutasyon yoksa F1 ve F2 kuşaklarının Hardy-Weinberg denge durumu nedir?', 'F1 kuşağının tamamı heterozigot olup dengede değildir; F2 kuşağı ise Hardy-Weinberg dengesine ulaşır', ['Başlangıçta eşleşme rastgele olduğu için F1 kuşağı doğrudan Hardy-Weinberg dengesinde doğar', 'F1 ve F2 kuşakları dengede olmayıp denge ancak 10. kuşaktan itibaren kurulabilir', 'Başlangıçta p ve q değerleri eşit olduğundan F0 kuşağı zaten Hardy-Weinberg dengesindedir'], 'F0\'da dişi (p=1) ve erkek (q=1) alel frekansları farklı olduğundan F1 %100 Aa olur (dengede değil); F1\'de her iki cinsiyette p=0,5 ve q=0,5 eşitlendiğinden F2 (0,25 AA : 0,50 Aa : 0,25 aa) tam dengeye oturur.'),
  ('A popülasyonunda bir alelin frekansı pA = 0,8 iken komşu B popülasyonunda aynı alelin frekansı pB = 0,3\'tür. Bir üreme mevsiminde A popülasyonunun %20\'si B\'den yeni göç eden bireylerden, %80\'i ise yerli bireylerden oluştuğuna göre A popülasyonunun yeni p frekansı kaçtır?', '0,70', ['0,55', '0,64', '0,75'], 'Göç sonrası yeni alel frekansı ağırlıklı ortalamayla bulunur: p_yeni = (0,80 × 0,8) + (0,20 × 0,3) = 0,64 + 0,06 = 0,70.'),
  ('Birbirinden tamamen izole edilmiş, her biri 10 bireyden oluşan 20 ayrı deneysel meyve sineği popülasyonunun tamamında başlangıçta A ve a alel frekansları p = 0,5 ve q = 0,5 olarak ayarlanmıştır. Seçilim ve mutasyon olmadan birçok nesil geçtikten sonra ne gözlenmesi beklenir?', 'Popülasyonların yaklaşık yarısında A alelinin, diğer yarısında a alelinin sabitlenmesi', ['20 popülasyonun tamamında p = 0,5 ve q = 0,5 dengesinin korunmaya devam etmesi', 'Baskın olduğu için 20 popülasyonun tamamında yalnızca A alelinin %100\'e ulaşması', 'Her bir küçük popülasyonun kendi içindeki heterozigotluk oranının %100\'e çıkması'], 'Küçük izole popülasyonlarda sürüklenme her popülasyonun iç çeşitliliğini sıfırlarken (fiksasyon), başlangıç frekansı 0,5 olduğundan grupların yaklaşık yarısı A\'ya, yarısı a\'ya sabitlenir; gruplar arası fark artar.'),
  ('Bir gen lokusundaki nötr bir alelin başlangıçtaki frekansı p = 0,15 ise ve popülasyonda yalnızca genetik sürüklenme etkiliyse, bu alelin uzun vadede popülasyonda sabitlenme (%100\'e ulaşma) olasılığı kaçtır?', '0,15', ['0,50', '0,0225', '0,85'], 'Nötr evrim ve genetik sürüklenme teorisine göre, seçilim baskısı olmayan bir alelin nihai olarak popülasyonda sabitlenme olasılığı doğrudan başlangıçtaki frekansına (p = 0,15) eşittir.'),
  ('Anakara üzerindeki bir kuş türünde kıyı şeridi rüzgarlı olduğu için kısa kanatlılık avantajlıdır; ancak iç kesimlerdeki geniş ormanda yaşayan uzun kanatlı kuşlar sürekli kıyıya göç etmektedir. Bu durumda kıyı popülasyonundaki gen akışının etkisi nedir?', 'Gen akışı, kıyı popülasyonunun yerel rüzgar koşullarına tam adaptasyonunu zorlaştırır', ['Gen akışı kıyıdaki kısa kanat alelinin bir nesilde %100 sabitlenmesini sağlar', 'İç kesimden gelen göçmenler kıyıya ulaştıkları anda kanat genlerini değiştirir', 'Göç olayı yalnızca nötr genleri etkilediği için kanat uzunluğu frekansını değiştirmez'], 'Doğal seçilim yerel uyumu (kısa kanat) desteklerken, farklı seçilim baskısı altındaki bölgeden gelen yoğun gen akışı uyumsuz alelleri (uzun kanat) sürekli taşıyarak yerel adaptasyonu frenler.'),
  ('ABD\'deki Eski Düzen Amiş (Old Order Amish) topluluğunda çok parmaklılık ve cücelikle seyreden çekinik "Ellis-van Creveld sendromu" sıklığının genel Amerikan nüfusuna göre çok yüksek olmasında hangi iki popülasyon genetiği faktörü birlikte rol oynamıştır?', 'Kurucu etkisiyle alelin başlangıçta yüksek oranda taşınması ve kapalı evliliklerle homozigotlaşması', ['Yüksek mutasyon hızlarının sürekli yeni hastalık geni üretmesi ve dışarıdan yoğun göç alınması', 'Sendromun heterozigot bireylere bulaşıcı hastalıklara karşı yüksek bağışıklık kazandırması', 'Büyük popülasyon hacmi sayesinde Hardy-Weinberg dengesinin kusursuz biçimde korunması'], 'Az sayıda kurucu aileden birinin bu aleli taşıması (kurucu etkisi) başlangıç q değerini yükseltmiş, topluluk içi kapalı evlilikler (inbreeding) ise q² genotip sıklığını artırmıştır.'),
  ('İki ayrı tarlada yetişen aynı türe ait mısır popülasyonlarından X tarlasında 600 bitki (p = 0,4) ve Y tarlasında 400 bitki (p = 0,9) bulunmaktadır. Bu iki tarladaki tüm tohumlar eşit oranda karıştırılıp tek bir büyük tarlaya ekilirse (rastgele eşleşme öncesi karmada) toplam p alel frekansı kaç olur?', '0,60', ['0,65', '0,50', '0,72'], 'Toplam 1000 bitkilik havuzda X\'in ağırlığı 0,6 ve Y\'nin ağırlığı 0,4\'tür. Birleşik alel frekansı p = (0,6 × 0,4) + (0,4 × 0,9) = 0,24 + 0,36 = 0,60 olur.'),
  ('Yalnızca genetik sürüklenmenin etkili olduğu izole bir ortamda etkili popülasyon büyüklüğü N = 10 olan küçük bir kemirgen grubunda başlangıç heterozigotluk oranı H₀ = 0,40\'tır. Bir nesil sonra beklenen heterozigotluk oranı H₁ = H₀ × (1 - 1/(2N)) formülüne göre kaç olur?', '0,38', ['0,20', '0,36', '0,39'], 'Formülde N = 10 yerine konulduğunda 1 / (2 × 10) = 1/20 = 0,05 kayıp yaşanır. H₁ = 0,40 × (1 - 0,05) = 0,40 × 0,95 = 0,38 bulunur.'),
  ('Sanayi Devrimi sırasında İngiltere\'de hava kirliliğiyle ağaç gövdelerinin kararması sonucu koyu renkli Biston betularia güvelerinin oranının %1\'den %95\'in üzerine çıkması, kirlilik önlendikten sonra tekrar açık renklilerin artması neyi gösterir?', 'Doğal seçilimin yönünün ve alel frekanslarının çevresel koşullara bağlı olarak tersine dönebildiğini', ['Genetik sürüklenmenin milyonlarca bireylik güve popülasyonunda her yıl yön değiştirdiğini', 'Kömür dumanının açık renkli güvelerin kanat genlerini doğrudan koyu gene dönüştürdüğünü', 'Açık renk alelinin baskınlıktan çekinikliğe geçerek kalıtım biçimini değiştirdiğini'], 'Biberli güve örneği, çevresel seçilim baskısı (avcı kuşların görsel avlanması) değiştiğinde yönlü doğal seçilimin alel frekanslarını dinamik ve tersinir biçimde değiştirdiğini kanıtlar.'),
  ('Bir gen lokusunda heterozigot bireylerin uyum başarısının her iki homozigottan daha DÜŞÜK olduğu "heterozigot dezavantajı" (underdominance) durumunda popülasyonun alel frekansları nasıl bir seyir izler?', 'Başlangıçta hangi alelin frekansı 0,5 eşiğinin üzerindeyse o alel sabitlenir, diğeri elenir', ['Her iki alel de 0,5 frekansında sonsuza kadar kararlı bir denge içinde korunur', 'Popülasyondaki tüm bireyler zamanla heterozigot genotipte toplanarak dengelenir', 'Alel frekansları başlangıç değerlerinden bağımsız olarak her zaman çekinik alele sabitlenir'], 'Kararsız denge yaratan heterozigot dezavantajında (örneğin kromozomal translokasyon taşıyıcılarında kısırlık), başlangıçta çoğunlukta olan (p > 0,5) alel hızla 1\'e giderken azınlıktaki alel yok olur.'),
  ('Dengedeki bir popülasyonda otozomal çekinik bir genetik bozukluğun taşıyıcı sıklığı (2pq) %18 olarak saptanmıştır (çekinik alel nadir olan aleldir, yani q < 0,5). Bu popülasyonda hasta doğacak bireylerin (q²) yüzdesi kaçtır?', '%1', ['%9', '%3', '%0,81'], '2pq = 0,18 ise pq = 0,09 ve p + q = 1\'dir. p = 0,9 ve q = 0,1 değerleri bu eşitliği sağlar (0,9 × 0,1 = 0,09 ve q < 0,5). Hasta birey oranı q² = (0,1)² = 0,01 yani %1\'dir.'),
  ('Bakteriler eşeysiz (ikiye bölünerek) üreyen haploid canlılar oldukları halde bir bakteri popülasyonunda komşu bakterilerden plazmit aktarımı (konjugasyon) yoluyla direnç geni alınması, ökaryot popülasyon genetiğindeki hangi mekanizmaya işlevsel olarak en çok benzer?', 'Popülasyonun gen havuzuna dışarıdan yeni alel katan gen akışına', ['Mevcut alellerin şans eseri kaybolmasına yol açan darboğaz etkisine', 'Akraba bireylerin çiftleşmesiyle ortaya çıkan soy içi üreme çöküşüne', 'Genotip frekanslarını sabit tutan Hardy-Weinberg rastgele eşleşmesine'], 'Yatay gen transferi (konjugasyon), dikey kalıtım dışında başka bir soy hattından veya popülasyondan genetik materyal girişi sağladığı için işlevsel olarak gen akışı (göç) ile paraleldir.'),
  ('Bir göldeki balık popülasyonunda A1 ve A2 eş baskın alelleri bulunmaktadır. Kirlilik sonrası yapılan sayımda A1A1 = 160, A1A2 = 480 ve A2A2 = 360 balık saptanmıştır. Kirlilikten bir nesil sonra da p = 0,4 ve q = 0,6 oranlarının ve aynı genotip yüzdelerinin korunduğu görülmüştür. Buna göre kirliliğin bu lokusa etkisi nedir?', 'İncelenen bu gen lokusu açısından seçilim baskısı yaratmamış ve Hardy-Weinberg dengesi korunmuştur', ['A1 aleline karşı çok güçlü yönlü doğal seçilim uygulayarak dengeyi bozmuştur', 'Heterozigot balıkların tamamını öldürerek popülasyonu darboğaza sokmuştur', 'A2 alelinin mutasyonla A1 aleline dönüşme hızını iki katına çıkarmıştır'], '1000 balıkta p = (320+480)/2000 = 0,4 ve q = 0,6\'dır. p²=0,16 (160), 2pq=0,48 (480), q²=0,36 (360) oranları tam dengededir ve sonraki nesilde de değişmemiştir; bu lokus kirliliğe karşı nötr kalmıştır.'),
  ('Otozomal BASKIN ve %100 öldürücü (üreme öncesi letal) bir alelin popülasyondaki elenme hızı ile otozomal ÇEKİNİK ve %100 öldürücü bir alelin elenme hızı karşılaştırıldığında hangisi doğrudur?', 'Baskın öldürücü alel heterozigotlarda da etkisini gösterdiği için tek bir nesilde tamamen elenir', ['Çekinik öldürücü alel her zaman baskın öldürücü alelden daha hızlı biçimde sıfırlanır', 'Her iki alel de Hardy-Weinberg yasası gereği tam olarak 10 nesilde gen havuzundan silinir', 'Baskın öldürücü alel taşıyıcılarda gizlendiği için popülasyonda sonsuza dek varlığını korur'], 'Tam baskın ve üreme öncesi öldürücü bir alel hem AA hem Aa bireyleri üreyemeden öldürdüğünden tek kuşakta gen havuzundan tamamen silinir (yalnızca yeni mutasyonlarla tekrar belirebilir).'),
  ('Bir nehir sisteminin üst kolunda yaşayan balık popülasyonunda p = 0,9 iken alt kolunda yaşayan balık popülasyonunda p = 0,1\'dir. Şelale engeli nedeniyle sadece üst koldan alt kola doğru tek yönlü balık geçişi (tek yönlü gen akışı) olmaktadır. Başka hiçbir evrimsel kuvvet yoksa çok uzun vadede ne olur?', 'Alt koldaki popülasyonun alel frekansı zamanla üst koldaki popülasyonun 0,9 değerine eşitlenir', ['Üst koldaki popülasyonun alel frekansı azalarak 0,50 orta noktasında buluşurlar', 'Şelale alt koldaki balıkları koruduğu için alt kolda p = 0,1 değeri hiç değişmez', 'Her iki koldaki balık popülasyonunda da p aleli tamamen yok olarak sıfırlanır'], 'Tek yönlü (kaynak-kuyu / anakara-ada tipi) gen akışında kaynak popülasyonun (üst kol) frekansı değişmezken, alıcı popülasyonun (alt kol) frekansı asimptotik olarak kaynağın frekansına (0,9) eşitlenir.'),
  ('Bir popülasyonda otozomal bir lokus için yapılan sayımda AA = 320, Aa = 320 ve aa = 360 birey tespit edilmiştir. Bu popülasyon tüm Hardy-Weinberg koşullarına uyarak rastgele eşleşirse bir sonraki nesilde (dengeye ulaştığında) beklenen heterozigot (Aa) birey yüzdesi kaç olur?', '%49,92', ['%32,00', '%50,00', '%48,00'], 'Mevcut 1000 bireyde (2000 alel) A sayısı = 640 + 320 = 960 olup p = 960/2000 = 0,48 ve q = 0,52\'dir. Rastgele eşleşmeyle 1 nesil sonra dengeye geldiğinde Aa oranı 2pq = 2 × 0,48 × 0,52 = 0,4992 yani %49,92 olur.'),
  ('Aşağıdaki dört farklı popülasyon senaryosundan hangisinde genetik çeşitliliğin (heterozigotluğun ve alel zenginliğinin) nesiller boyunca EN DÜŞÜK seviyeye inmesi beklenir?', 'Darboğaz geçirerek 12 bireye düşmüş ve komşularıyla bağlantısı tamamen kopmuş izole ada popülasyonunda', ['Komşu ormanlarla arasında geniş ekolojik koridorlar bulunan on bin bireylik geyik popülasyonunda', 'Sıtma bölgesinde heterozigot avantajının güçlü şekilde işlediği büyük bir insan popülasyonunda', 'Rüzgarla kilometrelerce uzağa polen gönderebilen geniş yayılışlı çayır otu popülasyonunda'], 'Hem darboğaz geçirmiş çok küçük nüfus (şiddetli genetik sürüklenme ve soy içi üreme) hem de tam coğrafi izolasyon (gen akışının sıfır olması) birleştiğinde genetik çeşitlilik hızla en alt düzeye çöker.'),
  ('Vücut hücrelerinde (somatik hücreler) meydana gelen bir nokta mutasyonunun eşeyli üreyen memeli bir türün evrimsel sürecine doğrudan katkıda bulunamamasının nedeni nedir?', 'Mutasyonun gametler aracılığıyla gelecek kuşaklara aktarılamaması', ['Somatik hücrelerdeki DNA onarım mekanizmalarının mutasyonu anında silmesi', 'Vücut hücrelerindeki genlerin protein sentezinde hiçbir zaman görev almaması', 'Doğal seçilimin yalnızca embriyonik dönemde oluşan mutasyonları tanıması'], 'Eşeyli üreyen canlılarda yalnız üreme ana hücrelerinde veya gametlerde gerçekleşen kalıtsal mutasyonlar yavrulara geçerek evrimsel sürece katılabilir.'),
  ('Bir araştırmacı, karanlık mağaralarda yaşayan kör balıkların gözlerinin "kullanılmadığı için zamanla körelip yok olduğu" görüşünü savunmaktadır. Modern evrimsel biyoloji açısından bu görüş nasıl değerlendirilmelidir?', 'Yanlıştır; göz gelişimini baskılayan mutasyonlara sahip bireyler enerji tasarrufu sağlayarak doğal seçilimle avantaj kazanmıştır', ['Doğrudur; karanlıkta kullanılmayan organların genleri kendiliğinden silinerek yavrulara körelmiş olarak aktarılır', 'Yanlıştır; mağara sularındaki düşük sıcaklık göz merceği proteinlerinin sentezini kalıcı ve geri dönüşsüz durdurmuştur', 'Doğrudur; bireylerin yaşamları boyunca kullanmadıkları dokulardaki modifikasyonlar doğrudan eşey hücrelerine kopyalanır'], '"Kullanma ve kullanmama" Lamarckçı bir yanılgıdır; mağarada göz gibi maliyetli bir organı oluşturmayan mutant bireyler enerji avantajıyla seçilmiştir.'),
  ('Antibiyotik tedavisini doktorun önerdiği süreden önce, hastalık belirtileri hafifler hafiflemez yarıda bırakan bir hastada dirençli bakteri suşlarının gelişme riskinin yükselmesinin evrimsel açıklaması nedir?', 'Orta düzeyde dirençli bakterilerin yok edilemeyip çoğalarak daha yüksek direnç mutasyonları biriktirmesi', ['Düşük dozda kalan antibiyotiğin insan bağışıklık hücrelerini baskılayarak bakterileri beslemesi', 'Yarıda bırakılan ilacın bakteri sitoplazmasında plazmit DNA sentezini kimyasal olarak hızlandırması', 'Hastalık belirtileri geçtiğinde zararsız bakterilerin hastalık yapıcı türlere dönüşmeye başlaması'], 'Tedavi erken kesildiğinde en duyarlı bakteriler ölür ancak kısmen dirençli olanlar sağ kalır; bunlar hızla çoğalarak tam dirençli yeni bir popülasyon oluşturur.'),
  ('Bir bakteri kültürü eş zamanlı olarak üç ayrı antibiyotik içeren bir besi yerine ekildiğinde dirençli koloni oluşma olasılığının, tek antibiyotikli besi yerine göre çok daha düşük olmasının matematiksel ve genetik nedeni nedir?', 'Bir bakterinin üç bağımsız direnç mutasyonunu aynı anda taşıma olasılığının tekil olasılıkların çarpımına eşit olması', ['Üç farklı antibiyotiğin besi yerinde birleşerek tüm bakterilerin hücre zarını anında eriten asidik bileşik oluşturması', 'Bakterilerin aynı anda en fazla bir adet plazmit DNA molekülü bulundurabilme sınırına sahip olması', 'Çoklu antibiyotik varlığında bakterilerin ribozom sentezini tamamen durdurarak spor formuna geçememesi'], 'Bağımsız mutasyonların aynı hücrede bir arada bulunma olasılığı her birinin tekil olasılıklarının çarpımı kadardır (örneğin 10^-7 x 10^-7 x 10^-7), bu da son derece küçüktür.'),
  ('Bir geyik popülasyonunda çok küçük boynuzlu erkeklerin yırtıcılara karşı savunmasız kaldığı, aşırı büyük ve ağır boynuzlu erkeklerin ise sık ormanda koşarken ağaçlara takılarak av olduğu gözlemlenmiştir. Uzun vadede bu popülasyonda boynuz büyüklüğü dağılımının nasıl değişmesi beklenir?', 'Orta büyüklükte boynuza sahip bireylerin sıklığı artarken her iki uçtaki fenotiplerin oranı azalır', ['Boynuz oluşumunu sağlayan tüm genler popülasyondan elenerek tamamen boynuzsuz bir tür ortaya çıkar', 'Popülasyon küçük boynuzlu ova geyikleri ve dev boynuzlu orman geyikleri olarak iki ayrı gruba bölünür', 'Aşırı büyük boynuzlu erkekler dişiler tarafından seçileceği için boynuz ağırlığı sınırsız biçimde artar'], 'Sık orman ve yırtıcı baskısı hem çok küçük hem de çok büyük boynuzluları elediği için dengeleyici seçilim işler ve orta boynuzlu bireyler yaygınlaşır.'),
  ('"Doğal seçilim canlının ihtiyaç duyduğu en mükemmel genetik yapıyı sıfırdan tasarlayan kusursuz bir mühendistir." önermesi evrimsel biyoloji ilkelerine göre neden hatalıdır?', 'Doğal seçilim yalnızca o an popülasyonda mevcut olan rastgele varyasyonlar arasından ayıklama yapabilir, hedefe yönelik gen tasarlayamaz', ['Doğal seçilim yalnız eşeysiz üreyen tek hücreli canlılarda kusursuz çalışırken çok hücreli canlılarda tamamen etkisiz kalır', 'Mükemmel genetik yapıyı tasarlayan mekanizma doğal seçilim değil, bireylerin çevreye uyum sağlama isteğiyle oluşan mutasyonlardır', 'Doğal seçilim her kuşakta popülasyondaki tüm çekinik hastalık genlerini yüzde yüz başarıyla temizleyerek kusursuzluğu zaten sağlar'], 'Doğal seçilim ileri görüşlü veya amaçlı bir tasarımcı değildir; eldeki mevcut kalıtsal çeşitlilik üzerinde o anki çevre koşullarına göre eleme yapar.'),
  ('DNA\'da meydana gelen ve bir amino asit kodonunu yine aynı amino asidi şifreleyen başka bir kodona dönüştüren "sessiz mutasyonlar" hakkında hangisi söylenebilir?', 'Üretilen proteinin amino asit dizisini değiştirmediği için genellikle doğal seçilim açısından nötr etki gösterir', ['Hücredeki tüm protein sentezini anında durdurduğu için embriyonik dönemde kesinlikle ölümcül sonuç doğurur', 'Dengeleyici seçilim tarafından her zaman elenerek popülasyondaki gen havuzundan bir kuşakta temizlenir', 'Canlıya her koşulda üstün bir adaptasyon kazandırdığı için yönlü seçilimle hızla sabitlenir'], 'Genetik kodun dejenereliği nedeniyle aynı amino asidi kodlayan eş anlamlı değişimler fenotipi etkilemediğinde doğal seçilimin doğrudan baskısına uğramaz (nötr kalır).'),
  ('Eşeysiz üreyen bir amip popülasyonu ile eşeyli üreyen bir böcek popülasyonu ani ve sert bir çevresel yıkımla karşılaştığında, böcek popülasyonunun tür olarak hayatta kalma şansının daha yüksek olmasının temel sebebi nedir?', 'Mayoz ve döllenme sayesinde gen havuzunda çok daha geniş fenotipik varyasyon kombinasyonları barındırması', ['Böceklerin çevresel tehlikeyi sezdiğinde amiplere kıyasla yüz kat daha hızlı yararlı mutasyon geçirebilmesi', 'Eşeysiz üreyen canlılarda DNA replikasyonu sırasında hiçbir zaman nükleotit eşleşme hatası gerçekleşmemesi', 'Çok hücreli organizmaların tamamının çevresel stres altında uyku (endospor) formuna geçebilme yeteneği taşıması'], 'Eşeyli üreme her kuşakta rekombinasyonla farklı alel bileşimleri ürettiğinden, değişen ortama uyum sağlayabilecek en az birkaç bireyin bulunma olasılığını artırır.'),
  ('Bir kertenkele popülasyonunda bacak uzunluğu ortalaması 4 cm\'dir. Kasırga sonrası adadaki ince dallı çalılar yok olup yalnız geniş gövdeli dev ağaçlar kaldığında, birkaç kuşak sonra ortalama bacak uzunluğunun 5,2 cm\'ye çıktığı saptanmıştır. Bu süreçle ilgili hangisi doğrudur?', 'Geniş ağaç gövdelerine tutunmada uzun bacaklı varyantlar seçilerek popülasyon ortalaması yönlü olarak kaymıştır', ['Kasırgadan kurtulan kertenkelelerin ağaçlara tırmanma çabası bacak kemiklerini uzatarak yavrulara geçmiştir', 'Dengeleyici seçilim etkisiyle hem 3 cm hem de 5 cm bacaklı bireyler aynı oranda elenmiştir', 'Popülasyondaki genetik çeşitlilik artarak 2 cm ve 6 cm bacaklı iki ayrı uç grup oluşmuştur'], 'Çevre koşulu (tutunma yüzeyi) değiştiğinde uzun bacaklı bireylerin avlanmaktan kurtulma ve üreme başarısı artmış, yönlü seçilim ortalamayı 4 cm\'den 5,2 cm\'ye taşımıştır.'),
  ('Bazı bitki türlerinde kromozom takım sayısının katlanmasıyla oluşan poliploidi (örneğin 2n yerine 4n kromozomlu olma) durumu evrimsel açıdan nasıl bir rol oynar?', 'Tek bir kuşakta ata türle üreme yalıtımı yaratarak ani türleşmeye ve yeni genetik varyasyona kaynaklık eder', ['Bitkinin fotosentez yeteneğini tamamen yok ettiği için her zaman ilk kuşakta ölümle sonuçlanır', 'Yalnızca yaprak hücrelerinde gerçekleşen kalıtsal olmayan bir modifikasyon olduğu için evrimi etkilemez', 'Dengeleyici seçilimin en tipik sonucu olarak mevcut diploid bireylerin kromozom sayısını sabit tutar'], 'Poliploidi özellikle bitkilerde yaygın bir genom mutasyonudur; oluşan tetraploid (4n) bireyler diploid (2n) atalarıyla verimli döl veremediğinden hızlı türleşmeye yol açar.'),
  ('Bir çiftlikte et verimini artırmak için yemlere sürekli düşük dozda antibiyotik karıştırılması uygulamasının insan sağlığı açısından oluşturduğu en büyük evrimsel tehlike nedir?', 'Hayvanların sindirim sisteminde seçilen antibiyotik dirençli bakterilerin besin zinciri veya temasla insanlara bulaşması', ['Antibiyotiklerin hayvanların kas hücrelerinde birikerek insanlarda doğrudan orak hücreli anemi mutasyonu başlatması', 'Düşük doz antibiyotiğin çiftlik hayvanlarının üreme yeteneğini yok ederek hayvansal gıda üretimini bitirmesi', 'Hayvanlardaki tüm zararsız bakterilerin virüslere dönüşerek hava yoluyla kıtalar arası salgın başlatması'], 'Hayvancılıkta büyümeyi hızlandırmak için rutin antibiyotik kullanımı devasa bir yönlü seçilim havuzu yaratarak dirençli bakterilerin seçilmesine ve insanlara geçmesine neden olur.'),
  ('Kistik fibrozis hastalığına neden olan çekinik alelin homozigot durumda ağır sağlık sorunlarına yol açmasına rağmen Avrupa kökenli insan popülasyonlarında beklenenden yüksek sıklıkta korunmuş olmasıyla ilgili "heterozigot avantajı" hipotezi neyi öne sürer?', 'Taşıyıcı (heterozigot) bireylerin tifo veya kolera gibi aşırı sıvı kaybettiren enfeksiyonlara karşı geçmişte dirençli olduğunu', ['Kistik fibrozis alelinin her kuşakta baskın alele dönüşerek tüm sağlıklı bireyleri hasta hale getirdiğini', 'Avrupa\'daki soğuk iklimin insan akciğer hücrelerinde bu mutasyonu her kış yeniden zorunlu olarak oluşturduğunu', 'Yönlü seçilimin homozigot hasta bireylere sağlıklı bireylerden çok daha yüksek doğurganlık kazandırdığını'], 'Tıpkı orak hücre-sıtma ilişkisinde olduğu gibi, kistik fibrozis taşıyıcılarının geçmişteki ölümcül bağırsak enfeksiyonlarında su kaybına daha dirençli kalarak dengeleyici seçilimle korunduğu düşünülmektedir.'),
  ('Penisilin antibiyotiği bakterilerde hücre duvarındaki peptidoglikan sentezini engelleyerek etki gösterir. Buna göre aşağıdaki patojenlerden hangisinde penisiline karşı doğal (yapısal) bir etkisizlik görülür ve yönlü seçilim baskısı oluşmaz?', 'Hücre duvarı bulunmayan Mikoplazma cinsi bakterilerde', ['Kalın peptidoglikan tabakalı Gram-pozitif kok bakterilerinde', 'Bölünerek hızla çoğalan hastalık yapıcı boğaz bakterilerinde', 'Yalnızca açık yaralarda enfeksiyon oluşturan deri bakterilerinde'], 'Mikoplazmalar doğal olarak hücre duvarına sahip olmadığından hücre duvarı sentezini hedef alan penisilinden etkilenmez; ilaç seçici bir baskı oluşturamaz.'),
  ('Bir ada kertenkelesi popülasyonunda yılan saldırılarından kaçmak için çok hızlı koşabilen uzun bacaklılarla, dar kaya çatlaklarına hızla saklanabilen çok kısa bacaklıların hayatta kaldığı; orta uzunlukta bacaklıların ise ne yeterince hızlı koşabildiği ne de çatlaklara sığabildiği saptanmıştır. Ancak birkaç yıl sonra yılanların adadan tamamen yok olduğu ve yalnızca ağaç kabuklarındaki böceklerle beslenmenin belirleyici olduğu görülmüştür. Seçilim türü sırasıyla nasıl değişmiştir?', 'Önce dallandırıcı seçilim etkiliyken yılanlar yok olduktan sonra yeni beslenme koşuluna göre yönlü veya dengeleyici seçilime dönmüştür', ['Başlangıçta dengeleyici seçilim varken yılanların yok olmasıyla birlikte yapay seçilim mekanizması başlamıştır', 'İlk dönemde eşeysel seçilim baskınken yılanların adadan ayrılmasıyla tüm doğal seçilim süreçleri sonsuza dek durmuştur', 'Her iki dönemde de yalnızca orta bacak uzunluğuna sahip bireyler seçilerek varyasyon tamamen sıfırlanmıştır'], 'İlk durumda iki uç (çok uzun ve çok kısa) avantajlı olup ortadakiler elendiği için dallandırıcı seçilim vardır; yılan baskısı kalkınca seçilim rejimi yeni ekolojik duruma göre değişir.'),
  ('Bir virüs türünün konak canlıda çok kısa sürede ölümcül etki yaratacak bir mutasyon geçirmesi, virüsün kendi evrimsel başarısını (yayılmasını) bazen olumsuz etkileyebilir. Bu durumun nedeni nedir?', 'Konağın başka bireylere virüsü bulaştıramadan çok hızlı ölmesinin virüsün üreme ve yayılma zincirini kırması', ['Ölümcül mutasyon geçiren tüm virüslerin konak hücreye girer girmez ribozomlarını kaybederek parçalanması', 'Doğal seçilimin virüsler ve bakteriler gibi mikroskobik varlıklar üzerinde hiçbir şekilde etkili olamaması', 'Konak canlının ölümcül virüsle karşılaştığında kendi DNA\'sını değiştirerek anında ölümsüzlük kazanması'], 'Bulaşıcı ajanlarda aşırı öldürücülük, konak yeni bireylere hastalığı bulaştıramadan ölürse patojenin de onunla birlikte yok olmasına yol açarak seçilim dezavantajı yaratabilir.'),
  ('Sanayi melanizmi araştırmalarında H. B. D. Kettlewell\'in kirli ve temiz ormanlarda işaretli açık ve koyu renkli güveleri serbest bırakıp tekrar yakalama deneyleri yapmasının bilimsel amacı nedir?', 'Kuş avcılığının farklı zemin renklerinde güve fenotipleri üzerinde seçici bir baskı oluşturduğunu deneysel olarak test etmek', ['Ağaç kabuklarındaki kömür kurumunun açık renkli güvelerin kanat pullarını kimyasal olarak siyaha boyadığını kanıtlamak', 'Koyu renkli güvelerin açık renkli güvelerle çiftleşemediğini ve tamamen ayrı bir biyolojik tür olduğunu göstermek', 'Güvelerin gece uçuş hızlarının fabrika dumanındaki karbondioksit oranıyla doğru orantılı arttığını ölçmek'], 'Kettlewell, serbest bırakılan işaretli güvelerin kirli ve temiz ormanlarda hayatta kalma oranlarını ölçerek görsel avcıların (kuşların) yönlü doğal seçilim ajanı olduğunu doğrulamıştır.'),
  ('Tarım zararlısı böceklere karşı genetiği değiştirilmiş (Bt toksini üreten) mısır ekilen tarlaların kenarına, Ziraat Mühendislerinin bilerek %20 oranında toksin üretmeyen normal mısır ("sığınak alan") ektirmesi hangi evrimsel amaca hizmet eder?', 'Sığınak alanda çoğalan duyarlı böceklerin dirençli böceklerle çiftleşmesini sağlayarak direnç alelinin homozigotlaşıp yayılmasını geciktirmek', ['Normal mısırlardan yayılan polenlerin böceklerin sindirim sistemindeki direnç genlerini tamamen silmesini sağlamak', 'Böceklerin lezzet farkını öğrenerek genetiği değiştirilmiş mısır tarlasına girmekten kendi istekleriyle vazgeçmesini öğretmek', 'Dallandırıcı seçilimi hızlandırarak tarlada birbirini yiyen iki farklı etçil böcek türünün evrimleşmesini tetiklemek'], 'Sığınak stratejisi evrimsel biyolojinin tarımdaki doğrudan uygulamasıdır; duyarlı böceklerin gen havuzunda kalmasını sağlayarak çekinik direnç alellerinin hızla sabitlenmesini önler.'),
  ('Bir balık popülasyonunda avcıların her zaman en iri balıkları hedef aldığı ticari balıkçılık faaliyetleri onlarca yıl sürdüğünde, o balık türünün ortalama üreme yaşı ve vücut boyunda nasıl bir evrimsel değişim gözlenir?', 'Erken yaşta ve daha küçük boyda eşeysel olgunluğa erişen bireyler seçilerek popülasyonun ortalama boyu küçülür', ['Balıklar ağlardan kaçabilmek için birkaç kuşak içinde dev boyutlara ulaşarak balinalarla rekabet etmeye başlar', 'Dengeleyici seçilim devreye girerek balıkların üreme yaşını ve boy uzunluğunu avcılık öncesi değerde sabit tutar', 'Ağlarla yakalanma korkusu balıkların hipofiz bezinde büyüme hormonu genini silerek kısır bireyler oluşturur'], 'İri bireyler üreyemeden ağlarla toplandığında (insan kaynaklı yönlü seçilim), daha küçük boyda ve erken yaşta üreyebilen genotipler gen havuzuna daha çok katkıda bulunur.'),
  ('"Aynı türe ait sağlıklı bireylerin tamamı doğal seçilim karşısında eşit üreme şansına sahiptir." görüşünü savunan bir öğrenciye aşağıdaki bilimsel kanıtlardan hangisi sunularak hatası düzeltilmelidir?', 'Sağlıklı bireyler arasında da kamuflaj, besin bulma ve eş seçimi bakımından kalıtsal farklar bulunduğundan üreme başarıları farklıdır', ['Doğal seçilim yalnızca hasta ve sakat doğan bireyleri ölüme terk ederken geri kalan tüm bireylerin eşit sayıda yavru yapmasını sağlar', 'Bir türün tüm sağlıklı bireyleri yüzde yüz aynı DNA dizilimine sahip olduğu için aralarında hiçbir seçilim farkı oluşamaz', 'Üreme şansını belirleyen tek etken bireyin doğduğu mevsim olup genetik yapının hayatta kalmada hiçbir payı yoktur'], 'Doğal seçilim yalnızca "ölümcül hastalık/sağlıklılık" ayrımı yapmaz; sağlıklı bireyler arasındaki küçük kalıtsal varyasyonlar bile diferansiyel (farklılaşmış) üreme başarısına yol açar.'),
  ('Avustralya\'da hızla çoğalan Avrupa tavşanlarını kontrol altına almak için 1950\'lerde miksoma virüsü salındığında ilk salgında tavşanların %99,8\'i ölmüş, ancak sonraki yıllarda ölüm oranı belirgin biçimde düşmüştür. Bu süreçte tavşan ve virüs popülasyonlarında birlikte gerçekleşen evrimsel değişim nedir?', 'Tavşanlarda virüse dirençli bireyler seçilirken, virüste de konağı hemen öldürmeyip bulaşmayı sürdüren orta şiddetli suşlar seçilmiştir', ['Sağ kalan tavşanlar virüs DNA\'sını sindirim enzimleriyle parçalayıp kendi yavrularına aşı yoluyla aktarmaya başlamıştır', 'Miksoma virüsü Avustralya\'nın sıcak ikliminde mutasyon geçirerek tavşanlar için yararlı bir vitamin üreticisine dönüşmüştür', 'Tavşanlar eşeyli üremeyi bırakıp eşeysiz üremeye geçerek virüsün hücre zarındaki reseptörlere bağlanmasını engellemiştir'], 'Bu durum birlikte evrime (koevolüsyon) klasik bir örnektir: Tavşanlarda bağışıklık direnci yüksek olanlar yönlü seçilimle artarken, aşırı öldürücü virüs suşları konakla birlikte yok olup orta virülanslı suşlar seçilmiştir.'),
  ('Yeni bir antibiyotik piyasaya sürüldükten birkaç yıl sonra hastanelerde bu ilaca dirençli bakteri vakalarının rapor edilmesi neden "evrimsel olarak kaçınılmaz" bir süreç olarak değerlendirilir?', 'Milyarlarca bakteriden oluşan popülasyonlarda DNA replikasyonu ve yatay gen transferi sürdükçe seçici baskı altında dirençli varyantların mutlaka seçileceği için', ['Üretilen her antibiyotik molekülünün belirli bir raf ömrü sonunda kimyasal olarak bozunup bakteriler için büyüme hormonuna dönüştüğü için', 'İnsan vücudunun yeni antibiyotikleri yabancı madde sayıp parçalayarak bakterileri korumak üzere özel enzimler salgıladığı için', 'Bakterilerin sinir sistemleriyle ilacın kimyasal formülünü analiz edip ona uygun panzehir genini laboratuvar hızında tasarlayabildiği için'], 'Yüksek üreme hızı, mutasyon ve plazmit transferi (konjugasyon) varlığında antibiyotik kullanımı güçlü bir yönlü seçilim uygular; dirençli suşların baskınlaşması evrimsel bir sonuçtur.'),
  ('Yetişkin insanlarda süt şekerini sindiren laktaz enziminin üretiminin bebeklikten sonra durması memelilerde genel kuralken, tarihsel olarak hayvancılık ve süt tüketimi yapılan Kuzey Avrupa ve Doğu Afrika topluluklarında yetişkinlikte de laktaz üretiminin sürmesi (laktaz kalıcılığı) nasıl açıklanır?', 'Sütün önemli bir besin ve su kaynağı olduğu kültürlerde laktaz genini açık tutan mutasyonlara sahip bireylerin yönlü seçilimle yüksek hayatta kalma başarısı göstermesiyle', ['Süt içmeye devam eden yetişkinlerin bağırsak hücrelerinin zorlanarak DNA\'larında yeni bir laktaz geni yaratıp bunu çocuklarına aktarmasıyla', 'Kuzey Avrupa\'daki soğuk havanın sindirim enzimlerinin bozulmasını önleyerek kalıtsal olmayan bir modifikasyon oluşturmasıyla', 'Süt tüketen topluluklarda dallandırıcı seçilimle et yiyenler ve süt içenler olmak üzere iki ayrı insan türünün ortaya çıkmasıyla'], 'Laktaz kalıcılığı gen-kültür birlikte evriminin ve insanlarda yakın geçmişte gerçekleşmiş yönlü doğal seçilimin en iyi belgelenmiş örneklerinden biridir; farklı kıtalarda bağımsız mutasyonlar seçilmiştir.'),
  ('Bir bilim insanı "Mutasyonlar tamamen rastgeledir; doğal seçilim ise rastgele değildir." dediğinde bu iki mekanizmanın işleyişine dair hangi temel ayrımı vurgulamaktadır?', 'Mutasyonların canlının işine yarayıp yaramayacağından bağımsız oluştuğunu, doğal seçilimin ise çevreye uyumlu olanları sistemli biçimde ayıkladığını', ['Mutasyonların yalnız laboratuvar ortamında gerçekleştiğini, doğal seçilimin ise yalnız vahşi doğadaki ormanlarda görüldüğünü', 'Mutasyonların her zaman eşit zaman aralıklarıyla meydana geldiğini, doğal seçilimin ise yazı tura atışı gibi şansa bağlı olduğunu', 'Mutasyonların yalnız çekinik genlerde oluştuğunu, doğal seçilimin ise her koşulda yalnız baskın genleri koruduğunu'], 'Mutasyon organizmanın ihtiyacına göre yönlendirilmez (rastgeledir); buna karşılık doğal seçilim hayatta kalma ve üreme başarısına dayalı deterministik/seçici bir süzgeçtir (rastgele değildir).'),
  ('İki ayrı bitki türünün (A türü: 2n=14, B türü: 2n=18) melezlenmesi ve ardından kromozom sayısının kendiliğinden iki katına çıkmasıyla oluşan verimli allopoliploid yeni türün diploit kromozom sayısı kaçtır?', '32', ['16', '64', '28'], 'A türünden n=7, B türünden n=9 kromozomlu gametler birleşerek 16 kromozomlu kısır melezi oluşturur; kromozom katlanmasıyla 2n=32 kromozomlu verimli allopoliploid tür meydana gelir.'),
  ('Tetraploit (4n) bir çuha çiçeğinin ata diploit (2n) çuha çiçeğiyle tozlaşması sonucunda yeni nesillerin devam edememesinin temel sitogenetik nedeni aşağıdakilerden hangisidir?', 'Oluşan 3n (triploit) melezlerin mayoz bölünmede dengeli gamet üretememesi', ['4n bitkinin polen tüpünün kendi türünde dahi hiç çimlenememesi', 'Diploit bitkinin tüm hücrelerinde mitoz bölünmenin tamamen durması', 'Triploit tohumların döllenme anında kromozomlarını tamamen kaybetmesi'], '4n bitkiden gelen 2n gamet ile 2n bitkiden gelen n gamet birleştiğinde 3n (triploit) döl oluşur; tek sayılı kromozom takımları mayozda homolog eşleşme sorunu yaşadığı için birey kısır olur.'),
  ('Üreme engelleri açısından değerlendirildiğinde, doğal seçilimin zigot öncesi engelleri zigot sonrası engellere göre evrimsel süreçte daha fazla desteklemesinin (pekiştirme/reinforcement) temel nedeni nedir?', 'Başarısız veya kısır melez üretimi için harcanacak zaman ve gamet enerjisinin önlenmesi', ['Zigot sonrası engellerin yalnızca tek hücreli ökaryot canlılarda görülebilmesi', 'Zigot öncesi engellerin DNA\'daki mutasyon oranını her nesilde artırması', 'Kısır melezlerin doğada ata türlerden çok daha fazla yavru üretebilmesi'], 'Kısır ya da ölü doğacak bir yavruya gamet ve bakım enerjisi yatırmak bireyin üreme başarısını düşürür; bu nedenle uyumsuz türlerle çiftleşmekten kaçınan (zigot öncesi engeli güçlü) bireyler doğal seçilimle avantaj kazanır.'),
  ('Bir dağ silsilesinin çevresini halka şeklinde saran martı popülasyonlarında, komşu popülasyonlar birbiriyle verimli döl verebilirken halkanın iki ucundaki uç popülasyonlar karşılaştıklarında çiftleşememektedir. "Halka tür" olarak bilinen bu durum neyi kanıtlar?', 'Türleşmenin kademeli genetik farklılaşmayla gerçekleşen sürekli bir süreç olduğunu', ['Yeni türlerin her zaman ani kromozom katlanmalarıyla bir gecede oluştuğunu', 'Gen akışının mesafe ne olursa olsun tüm popülasyonları aynı tuttuğunu', 'Üreme yalıtımının yalnızca deniz aşırı adalarda ortaya çıkabileceğini'], 'Halka türler, coğrafi mesafe boyunca kademeli değişen popülasyonların uç noktalarında tam üreme yalıtımına ulaşabildiğini canlı olarak gösteren evrimsel ara aşamalardır.'),
  ('İki böcek popülasyonu uzun süre coğrafi olarak ayrı kaldıktan sonra bariyer ortadan kalkmış ve popülasyonlar "melez kuşağı" adı verilen dar bir bölgede tekrar karşılaşmıştır. Eğer melezlerin uyum gücü ata türlerden belirgin şekilde düşük ancak sıfır değilse, uzun vadede aşağıdakilerden hangisinin gerçekleşmesi beklenir?', 'Seçilimin zigot öncesi engelleri güçlendirerek iki türün ayrımını kesinleştirmesi', ['İki popülasyonun birleşip tek bir homojen türe hızla geri dönmesi', 'Melez bireylerin ata türlerin tamamını rekabette eleyerek yok etmesi', 'Her iki ata türün de kromozom sayısını yarıya indirerek haploit kalması'], 'Melezlerin uyum gücü düşük olduğunda, kendi türünden eş seçen bireyler daha çok verimli döl bırakır; bu "pekiştirme" (reinforcement) süreci zigot öncesi engelleri kuvvetlendirir.'),
  ('Bir gölün kurumasıyla oluşan onlarca küçük su birikintisinde kalan balık popülasyonlarının, göl kuraklığı geçip tekrar birleştiğinde birbiriyle üreyemeyen 12 ayrı türe dönüştüğü saptanmıştır. Bu hızlı çeşitlenmede aşağıdaki faktörlerden hangisinin rolü EN AZDIR?', 'Büyük göl dönemindeki kesintisiz ve homojen gen akışı', ['Küçük su birikintilerinde etkili olan genetik sürüklenme', 'Her birikintideki farklı avcı ve besin kaynaklarının yarattığı doğal seçilim', 'Su birikintileri arasındaki kara parçalarının oluşturduğu allopatrik yalıtım'], 'Kesintisiz gen akışı farklılaşmayı önler; çeşitlenmeyi sağlayan asıl unsurlar gölün parçalanmasıyla oluşan allopatrik yalıtım, küçük popülasyonlardaki sürüklenme ve farklı seçilim baskılarıdır.'),
  ('Hayvanlarda poliploidi yoluyla simpatrik türleşmenin çiçekli bitkilere kıyasla çok daha nadir görülmesinin başlıca biyolojik nedenlerinden biri aşağıdakilerden hangisidir?', 'Hayvanlarda eşey belirleme mekanizmalarının ve embriyonik gelişimin kromozom dozajına çok duyarlı olması', ['Hayvan hücrelerinde iğ ipliklerinin yalnızca mitoz bölünme sırasında sentezlenebilmesi', 'Çiçekli bitkilerin tamamında DNA eşlenmesinin sitoplazma dışında gerçekleşmesi', 'Hayvanlarda eşeyli üreme sırasında krossing-over olayının hiçbir zaman görülmemesi'], 'Çoğu hayvanda eşey kromozomlarının oranı ve gen dozajı gelişimi sıkı kontrol eder; ayrıca bitkiler erselik yapıları ve vejetatif üremeleri sayesinde poliploid bireyin eş bulma sorununu kolayca aşar.'),
  ('Hawaii Takımadaları\'nın volkanik patlamalarla okyanus ortasında sırayla oluşması, "gümüşkılıç" (silversword) bitki grubunda olağanüstü bir uyumsal açılıma yol açmıştır. Okyanus adalarının ana karalara göre uyumsal açılım için çok elverişli olmasının temel nedeni nedir?', 'Başlangıçta rakip ve avcı türlerin azlığıyla birlikte adalar arası coğrafi yalıtımın bir arada bulunması', ['Ada topraklarında radyoaktif mutasyon hızının ana karalardan bin kat yüksek olması', 'Okyanus adalarındaki bitkilerin tamamının sadece eşeysiz sporlarla üreyebilmesi', 'Adalarda iklim koşullarının her gün kutup soğuğu ile çöl sıcağı arasında değişmesi'], 'Yeni oluşan izole adalarda boş ekolojik nişlerin bolluğu doğal seçilimle çeşitlenmeyi teşvik ederken, adalar arasındaki deniz engeli tekrarlayan kurucu etkisi ve allopatrik türleşmeyi hızlandırır.'),
  ('Amerika çöllerinde yaşayan kaktüs familyası (Cactaceae) ile Afrika çöllerinde yaşayan sütleğen familyasının (Euphorbiaceae) bazı türleri; etli gövdeleri, su depolama dokuları ve dikene dönüşmüş yapraklarıyla birbirine şaşırtıcı derecede benzer. DNA analizleri bu iki grubun çok uzak akraba olduğunu gösterdiğine göre bu benzerliğin nedeni nedir?', 'Benzer kurak çöl seçilim baskılarının yol açtığı yakınsak evrim', ['Kıtalar ayrıldıktan sonra aralarında devam eden yoğun polen akışı', 'Her iki bitki grubunun da aynı kurak yılda tek bir tohumdan türemesi', 'Çöl toprağındaki minerallerin bitki DNA dizilerini özdeş hale getirmesi'], 'Uzak akraba bitki ailelerinin benzer kuraklık stresi altında bağımsız olarak su depolayan gövde ve diken geliştirmesi yakınsak evrimin bitkiler dünyasındaki en güçlü örneklerindendir.'),
  ('Avustralya\'daki keseli memelilerden "keseli uçan sincap" (Petaurus) ile Kuzey Amerika\'daki plasentalı memelilerden "uçan sincap" (Glaucomys) ön ve arka üyeleri arasında uzanan deri zarları sayesinde ağaçtan ağaca süzülebilir. Bu iki türün durumuyla ilgili hangisi doğrudur?', 'Süzülme zarları yakınsak evrimle bağımsız gelişmiş analog yapılardır', ['İkisi de keseli memeliler alt sınıfında yer alan özdeş ikiz türlerdir', 'Çiftleştiklerinde doğada verimli döller verebilen aynı türün bireyleridir', 'Plasentalı uçan sincap doğrudan keseli uçan sincabın yavrusudur'], 'Keseli ve plasentalı memeliler evrimsel olarak çok erken ayrılmıştır; iki gruptaki süzülme zarları benzer ağaçsıl yaşam biçimine uyum olarak yakınsak evrimle ayrı ayrı ortaya çıkmıştır.'),
  ('Uçamayan kuşlardan devekuşu ve kivinin göğüs kemiklerinde uçuş kaslarının bağlandığı "karina" çıkıntısının bulunmaması ve kanatlarının çok küçük kalması hangi evrimsel çıkarımı destekler?', 'Uçabilen atalardan türedikleri ancak avcıların az olduğu ya da kara yaşamına uyum sağladıkları ortamlarda uçma yetisini ikincil olarak kaybettikleri', ['Kuşlar sınıfının evrimsel tarihinde henüz kanat gelişiminin yeni başladığı ve gelecekte uçacakları', 'Devekuşu ve kivinin memeliler sınıfından yakınsak evrimle tüylü yapı kazandığı', 'Körelmiş kanatların yalnızca eşeysiz üreyen omurgasız canlılarda ortaya çıkabileceği'], 'Kivi ve devekuşundaki işlevsiz küçük kanatlar körelmiş organlardır; uçmanın yüksek enerji maliyeti, uygun karasal/ada nişlerinde kanatların küçülmesi yönünde seçilim yaratmıştır.'),
  ('Ahtapotun (yumuşakça) gözü ile insanın (omurgalı) gözü; mercek, iris ve retina içermesi bakımından şaşırtıcı derecede benzer çalışır. Ancak insanda fotoreseptör sinirleri retinanın önünden geçtiği için "kör nokta" varken, ahtapotta sinirler retinanın arkasından çıktığı için kör nokta yoktur. Bu durum neyin kanıtıdır?', 'Karmaşık kamera tipi gözün iki şubede yakınsak evrimle bağımsız gelişen analog bir yapı olduğunun', ['İnsanların doğrudan kafadanbacaklı yumuşakçalardan ıraksak evrimle türediğinin', 'Ahtapot gözünün evrimsel süreçte işlevini yitirmiş körelmiş bir organ olduğunun', 'Omurgalılar ile yumuşakçalar arasında yakın zamanda yatay gen aktarımı yapıldığının'], 'Benzer görüntü oluşturma işlevine rağmen embriyonik doku kökenlerinin ve retina mimarisinin (kör nokta varlığı/yokluğu) farklı olması, bu iki gözün yakınsak evrim ürünü analog yapılar olduğunu gösterir.'),
  ('İnsan genomunda C vitamini (askorbik asit) sentezinin son basamağını yöneten GULO geninin mutasyonla bozulmuş ve işlevsiz bir "yalancı gen" (psödogen) halinde bulunması, diğer antropoid primatlarda da aynı mutasyonun görülmesi neyi kanıtlar?', 'İnsan ve diğer antropoid primatların meyvece zengin beslenen ortak bir atadan bu moleküler körelmiş yapıyı miras aldığını', ['İnsanların C vitaminini yalnızca güneş ışığı yardımıyla derilerinde sentezleyebildiğini', 'Yalancı genlerin yalnızca poliploidik bitki türlerinde işlevsel enzim ürettiğini', 'Yakınsak evrimin farklı kıtalardaki tüm memelilerde aynı baz çiftini sildiğini'], 'İşlevsiz GULO psödogeni, anatomik körelmiş organların moleküler düzeydeki karşılığıdır; aynı bozuk genin primatlarda paylaşılması ortak atanın en güçlü genetik kanıtlarından biridir.'),
  ('Soyu tükenmiş "Tiktaalik" fosili; balıklar gibi pul, solungaç ve yüzgeç ışınları taşırken, aynı zamanda kara omurgalıları (tetrapodlar) gibi yassı kafatası, hareketli boyun ve yüzgeç içinde el bileği kemiklerine homolog kemikler bulundurmaktadır. Bu fosilin evrimsel önemi nedir?', 'Sudan karaya geçiş sürecinde balıklar ile dört üyeli kara omurgalıları arasındaki evrimsel ara geçişi belgelemesi', ['Balıklarla sürüngenlerin günümüzde bile doğada çiftleşip kısır katırlar oluşturduğunu göstermesi', 'Kara omurgalılarının tamamının kuşlardan körelerek su altına geri döndüğünü kanıtlaması', 'Simpatrik poliploidinin yalnızca Devoniyen dönemindeki omurgalılarda gerçekleştiğini ispatlaması'], 'Tiktaalik gibi ara geçiş formları, hem ata grubun (lob yüzgeçli balıklar) hem de türemiş grubun (dört üyeli amfibiler) özelliklerini bir arada taşıyarak büyük evrimsel geçişleri somutlaştırır.'),
  ('İki orkide türü aynı yağmur ormanında yan yana yetişmektedir. Birinci türün çiçekleri yalnızca sabah 06.00-09.00 saatleri arasında açılıp öğlen kapanmakta, ikinci türün çiçekleri ise yalnızca akşam 18.00\'den sonra açılmaktadır. Bu iki tür arasındaki üreme yalıtımı için en doğru tanım hangisidir?', 'Zigot öncesi zamansal (gün içi) yalıtım', ['Zigot öncesi mekanik polen uyumsuzluğu', 'Zigot sonrası F1 melez kısırlığı', 'Allopatrik coğrafi bariyer yalıtımı'], 'Zamansal yalıtım yalnızca farklı mevsim veya yılları değil, günün farklı saatlerinde aktif olma veya çiçek açma durumlarını da kapsayan bir zigot öncesi üreme engelidir.'),
  ('Koyun (2n=54) ile keçinin (2n=60) çiftleşmesi sonucunda döllenme gerçekleşip zigot oluşabilmesine karşın, gelişmekte olan embriyonun gebeliğin erken evrelerinde anne karnında ölmesi hangi yalıtım mekanizmasına girer?', 'Zigot sonrası melez yaşayamazlığı', ['Zigot öncesi gametik yalıtım', 'Zigot öncesi mekanik yalıtım', 'Zigot sonrası F2 melez çöküşü'], 'Sperm yumurtayı dölleyip zigot oluşturduğu için tüm zigot öncesi engeller aşılmıştır; ancak genetik ve kromozomal dengesizlik embriyonun doğumdan önce ölmesine (melez yaşayamazlığına) yol açar.'),
  ('İki farklı pirinç (Oryza) hattının çaprazlanmasıyla elde edilen F1 kuşağı bitkiler gür büyüyüp bol tohum verirken, bu tohumlardan çıkan F2 kuşağı bitkilerin bodur kaldığı ve başak bağlayamadığı görülmüştür. Bu durumun genetik açıklaması nedir?', 'F2 kuşağında rekombinasyonla bir araya gelen uyumsuz gen kombinasyonlarının yol açtığı melez bozulması', ['F1 kuşağındaki bitkilerin çiçek açma mevsimlerinin birbirinden altı ay kayması', 'Polen tüpünün F1 çiçeğinin dişicik borusunda mekanik olarak sıkışıp kalması', 'Pirinç bitkilerinin tamamının ilk çaprazlamada triploit (3n) hale gelmesi'], 'F1 bireyleri her iki atadan tam birer haploit set aldığı için sağlıklı olabilir; ancak mayozdaki bağımsız dağılım ve krossing-over F2\'de uyumsuz epistatik alelleri bir araya getirerek melez bozulmasına neden olur.'),
  ('Simpatrik türleşmenin doğada gerçekleşebilmesi için allopatrik türleşmeden farklı olarak aşağıdaki koşullardan hangisinin mutlaka sağlanması gerekir?', 'Fiziksel engel bulunmadığı için gen akışını içeriden kesecek güçlü seçilim baskısı, eş tercihi veya poliploidinin ortaya çıkması', ['Popülasyonun arasına en az bin kilometre genişliğinde bir okyanus veya sıradağ girmesi', 'Popülasyondaki tüm bireylerin aynı anda eşeyli üremeyi bırakıp tomurcuklanmaya geçmesi', 'Üreme mevsimi boyunca dışarıdan komşu kıtalardan sürekli göçmen bireylerin katılması'], 'Fiziksel bariyer olmadığında rastgele çiftleşme (gen akışı) farklılaşmayı hemen siler; bu yüzden simpatrik türleşme ya poliploidi gibi ani kromozomal yalıtım ya da güçlü yıkıcı (dallandırıcı) seçilim ve seçici eşleşme gerektirir.'),
  ('Balina embriyolarının gelişim sürecinde önce arka bacak tomurcuklarının ve vücut kıllarının belirmesi, ancak doğumdan önce bacak tomurcuklarının programlı hücre ölümüyle gerileyip kaybolması neyi gösterir?', 'Kara memelisi atalarından kalan gelişimsel genlerin embriyoda hâlâ kısmen ifade edildiğini', ['Balinaların yaşlandıklarında tekrar karaya çıkıp yürümek için bacak geliştirdiğini', 'Yakınsak evrimin balık embriyolarında da kıl ve bacak tomurcuğu oluşturduğunu', 'Embriyonik gelişimin evrimsel geçmişle hiçbir genetik bağlantısının olmadığını'], 'Atalardan miras alınan bacak ve kıl gelişim genleri balina genomunda tamamen silinmemiş, gelişimin ileri evresinde düzenleyici genlerle baskılanmıştır; bu durum güçlü bir embriyolojik evrim kanıtıdır.'),
  ('Güney Kutbu\'nda yaşayan Antarktika buz balıkları ile Kuzey Kutbu sularında yaşayan morina balıkları, kanlarının donmasını önleyen "antifriz glikoproteinleri" üretir. Genetik incelemeler bu iki balık grubunun antifriz proteinlerini tamamen farklı ata genlerinden ve farklı amino asit dizileriyle ürettiğini ortaya koymuştur. Bu durum neyin kanıtıdır?', 'Moleküler düzeyde gerçekleşmiş yakınsak (konvergent) evrimin', ['İki kutup bölgesi arasında kesintisiz süren simpatrik gen akışının', 'Tüm kemikli balıkların ortak atasının buzullarda donarak yaşadığının', 'Antifriz genlerinin balıklarda işlevini kaybetmiş körelmiş psödogenler olduğunun'], 'İki uzak balık soyunun benzer dondurucu su sıcaklığı baskısı altında, farklı başlangıç genlerinden aynı fizyolojik işlevi gören antifriz moleküllerini bağımsız olarak evrimleştirmesi moleküler yakınsak evrimdir.'),
  ('Doğu Afrika\'daki Tanganika, Malavi ve Victoria göllerinin her birinde yüzlerce endemik çiklit balığı türü yaşar. Genetik ağaçlar, Malavi Gölü\'ndeki "kaya kazıyıcı" çiklitin, Tanganika Gölü\'ndeki ikizi kadar benzeyen "kaya kazıyıcı" çiklitten ziyade kendi gölündeki "balık avcısı" çiklite daha yakın akraba olduğunu göstermiştir. Bu bulgu nasıl yorumlanmalıdır?', 'Her gölde ayrı ayrı uyumsal açılım yaşanmış, farklı göllerdeki benzer beslenme tipleri ise yakınsak evrimle bağımsız gelişmiştir', ['Balıklar her gece göller arasındaki yüzlerce kilometrelik kurak karayı yürüyerek geçip çiftleşmektedir', 'DNA dizilimleri canlıların evrimsel akrabalık ilişkilerini belirlemede tamamen yanıltıcıdır', 'Tüm göllerdeki kaya kazıyıcı türler tek bir atadan türeyip sonradan diğer balıklara dönüşmüştür'], 'Her göl kendi ata türünden bağımsız bir uyumsal açılım (ıraksak evrim) geçirmiş; göllerdeki benzer ekolojik nişler (kaya yosunu kazıma, balık avlama vb.) ise göller arasında çarpıcı bir paralel/yakınsak evrim yaratmıştır.'),
  ('İki farklı kurbağa türü (Rana pipiens kompleksi) Kuzey Amerika\'da kuzeyden güneye doğru geniş bir yayılış gösterir. Kuzeydeki kurbağaların yumurtaları soğuk suya (5-10 °C), güneydekilerin yumurtaları ise sıcak suya (20-25 °C) uyumludur. Laboratuvarda kuzey ve güney uçtaki kurbağalar çaprazlandığında oluşan embriyolar anormal gelişip ölmektedir. Bu durum neyi gösterir?', 'Farklı iklimsel adaptasyonların yan ürünü olarak zigot sonrası melez yaşayamazlığının evrimleştiğini', ['Kurbağalar arasında çiftleşmeyi önleyen tam bir mekanik kilit-anahtar engeli bulunduğunu', 'Soğuk suyun kurbağa kromozomlarını eriterek eşeysiz üremeyi başlattığını', 'İki popülasyonun hiçbir zaman ortak bir amfibi ataya sahip olmadığını'], 'Popülasyonlar kendi yerel sıcaklıklarına doğal seçilimle uyum sağlarken embriyonik gelişim hızını yöneten genler farklılaşmış; bu genetik uyumsuzluk yan ürün olarak zigot sonrası üreme engeli (melez yaşayamazlığı) doğurmuştur.'),
  ('Yılanlarda göğüs kafesi omurlarının boyundan kuyruğa kadar uzanması ve ön bacakların hiç gelişmemesi, omurga bölgelerini belirleyen Hox genlerinin ifade alanlarının genişlemesiyle ilişkilidir. Bununla birlikte bazı ilkel yılanlarda (boalar ve pitonlar) kloak yanında küçük mahmuz şeklinde arka bacak kalıntıları görülür. Bu iki bulgu birlikte neyi doğrular?', 'Düzenleyici gelişim genlerindeki değişimlerin büyük vücut planı dönüşümlerine yol açarken körelmiş yapılarla atasal izleri koruyabildiğini', ['Yılanların solucanlardan doğrudan türeyip gelecekte dört bacaklı kertenkelelere dönüşeceğini', 'Hox genlerinin yalnızca bitkilerde taç yaprak ve polen üretimini kontrol ettiğini', 'Körelmiş arka mahmuzların yılanlarda uçmayı sağlayan analog kanat taslakları olduğunu'], 'Hox gen ifadelerindeki kayma ön üyelerin tamamen kaybını açıklarken, pitonlardaki pelvik mahmuzlar (körelmiş arka bacaklar) kertenkele benzeri dört bacaklı atalardan köken aldıklarını kanıtlar.'),
  ('Bir araştırmacı, aynı cins içindeki 5 farklı meyve sineği (Drosophila) çiftini inceleyerek genetik uzaklıkları ile üreme yalıtımı derecelerini karşılaştırmıştır. Veriler; genetik uzaklık çok azken çiftlerin kısmen melezlenebildiğini, genetik uzaklık arttıkça hem zigot öncesi hem zigot sonrası yalıtımın kademeli olarak tam (%100) değere ulaştığını göstermiştir. Bu araştırma neyi destekler?', 'Üreme yalıtımının ortak atadan ayrıldıktan sonra zaman içinde biriken genetik farklılıklarla kademeli olarak güçlendiğini', ['Türleşmenin genetik değişimden tamamen bağımsız olarak yalnızca iklim sıcaklığıyla belirlendiğini', 'Zigot sonrası engeller oluştuğunda zigot öncesi engellerin her zaman tamamen ortadan kalktığını', 'Meyve sineklerinde türleşmenin yalnızca kromozom sayısının üçe katlanmasıyla gerçekleştiğini'], 'Jerry Coyne ve H. Allen Orr\'un klasik Drosophila çalışmaları, üreme yalıtımının ortak atadan ayrılma süresi (genetik mesafe) arttıkça kademeli biçimde evrimleştiğini nicel olarak kanıtlamıştır.'),
  ('Yeni Zelanda\'da memeli kara avcılarının bulunmadığı milyonlarca yıl boyunca, orman zemininde yaşayan ve uçamayan bir papağan türü olan "kakapo" ile büyük bir çekirge türü olan "dev weta", anakaralardaki kemirgen memelilerin (fare/tavşan) ekolojik nişini doldurmuştur. Bu biyocoğrafik durum aşağıdakilerden hangisini gösterir?', 'Boş ekolojik nişlerin mevcut yerel taksonlar tarafından olağandışı adaptasyonlarla doldurulabildiğini', ['Ada ekosistemlerinde kuş ve böceklerin kısa sürede memeli sınıfına dönüştüğünü', 'Yeni Zelanda adalarının hiçbir zaman levha tektoniği veya izolasyon yaşamadığını', 'Uçma yeteneğinin kaybının her ortamda kuşların neslini anında tükettiğini'], 'Kara memelilerinin ulaşamadığı izole adalarda kuşlar ve böcekler, memelilerin bıraktığı boş yercil nişlere uyum sağlayarak uçmama ve devleşme (ada devleşmesi) gibi evrimsel özellikler geliştirmiştir.'),
  ('Bir gölde yaşayan dikence balığı (Gasterosteus aculeatus) popülasyonları buzul çağı sonunda denizden tatlı su göllerine geçtiğinde, denizdeki atalarında bulunan kemiksi yan zırh plakalarını ve karın dikeni çiftini büyük ölçüde kaybetmiştir. Araştırmalar bu kaybın farklı göllerde Pitx1 geninin pelvik düzenleyici bölgesindeki bağımsız delesyonlarla tekrar tekrar gerçekleştiğini göstermiştir. Bu durum hangi evrimi kanıtlar?', 'Benzer tatlı su seçilim baskıları altında paralel/yakınsak genetik adaptasyonu', ['Deniz balıklarının tatlı suya girer girmez kemiklerinin suda erimesiyle oluşan modifikasyonu', 'Tatlı su göllerindeki tüm balıkların poliploidi geçirerek kıkırdaklı balığa dönüştüğünü', 'Zırh plakalarının kaybının balıkların üreme başarısını her ortamda sıfıra indirdiğini'], 'Denizdeki büyük yırtıcı balıkların olmadığı ve kalsiyumun az olduğu tatlı su göllerinde zırh/diken kaybı avantaj sağlamış; bağımsız göl popülasyonları aynı düzenleyici mekanizma üzerinden paralel evrim geçirmiştir.'),
  ('Evrimsel biyolojide "körelmiş yapı" kavramıyla ilgili aşağıdaki yorumlardan hangisi bilimsel olarak YANLIŞTIR?', 'Bir yapının körelmiş sayılması için vücutta kesinlikle hiçbir ikincil fizyolojik görev üstlenmemesi şarttır', ['Körelmiş yapılar atasal türlerdeki tam işlevli organlarla homoloji gösterir', 'Atasal birincil işlevini yitirmiş bir yapı evrimsel süreçte küçük bir ikincil işlev kazanmış ya da korumuş olabilir', 'Körelmiş yapıların varlığı türlerin değişmez ve birbirinden bağımsız ortaya çıktığı görüşüyle çelişir'], 'Körelmiş (vestigial) yapılar atasal "birincil" işlevini kaybetmiş yapılardır (örneğin devekuşu kanadı uçma işlevini kaybetmiştir ancak kur yapma ve denge için kullanılır; insanda apandis sindirim işlevini yitirmiş ama lenfoid doku taşır).'),
  ('İki farklı bitki popülasyonu aynı dağın yamacında kesintisiz bir yayılış göstermektedir. Yamacın alt kısmında toprak ağır metallerle (bakır ve çinko) kirlenmişken, üst kısmında temiz toprak bulunmaktadır. Kirli topraktaki bitkiler ağır metal toleransı geliştirmiş ve temiz topraktaki akrabalarından iki hafta daha erken çiçek açacak şekilde evrimleşmiştir. Bu süreç literatürde hangi kavramla tanımlanır?', 'Gen akışına rağmen komşu nişlerde zamansal yalıtım geliştiren parapatrik/simpatrik türleşme eğilimi', ['Kıtaların ayrılmasıyla meydana gelen tam coğrafi (allopatrik) türleşme', 'İki farklı bitki familyasının yakınsak evrimle tek bir türde birleşmesi', 'Zigot sonrası F2 melez çöküşünün ağır metalleri topraktan temizlemesi'], 'Tatlı çayır otu (Anthoxanthum odoratum) üzerinde gözlemlenen bu klasik olayda, fiziksel engel olmaksızın bitişik (parapatrik) zıt toprak koşulları güçlü seçilim yaratmış ve çiçeklenme zamanının kayması üreme yalıtımını başlatmıştır.'),
  ('Memeli yumurtasını çevreleyen "zona pellucida" zarındaki ZP3 glikoprotein reseptörlerinin yalnızca kendi türünün sperm başındaki tamamlayıcı proteinleri tanıması ve akrozom reaksiyonunu başlatması, denizkestanelerinde ise spermdeki "bindin" proteininin yalnızca kendi türünün yumurta reseptörüne bağlanması neyi gösterir?', 'İç döllenme ve dış döllenme yapan hayvanların her ikisinde de moleküler düzeyde gametik yalıtımın işlediğini', ['Gametik yalıtımın yalnızca suya yumurta bırakan omurgasız hayvanlara özgü olduğunu', 'Sperm ve yumurta zarındaki proteinlerin tüm hayvanlar aleminde %100 aynı olduğunu', 'Zigot sonrası melez kısırlığının döllenmeden önce yumurta zarında gerçekleştiğini'], 'Gametik yalıtım dış döllenme yapan deniz canlılarında çok kritik olmakla birlikte, iç döllenme yapan memelilerde de zona pellucida reseptör özgüllüğü ile türler arası döllenmeyi engelleyen son zigot öncesi kapıdır.'),
  ('Evrimsel soyağaçları (filogenetik ağaçlar) oluşturulurken bilim insanlarının "analog" karakterler yerine özellikle "homolog" karakterleri ve DNA dizilerini kullanmaya özen göstermesinin nedeni nedir?', 'Analog yapıların ortak soyu değil benzer çevre baskısını yansıtması nedeniyle yanlış akrabalık gruplamalarına yol açabilmesi', ['Analog organların yalnızca fosilleşmiş tek hücreli arkelerde bulunabilmesi', 'Homolog organların her zaman birebir aynı görevi yapan dış iskelet yapıları olması', 'DNA dizilerinin evrimsel süreçte hiçbir zaman mutasyonla değişmemesi'], 'Yarasa ve kelebeği "kanatlılar" diye aynı yakın dala koymak yakınsak evrimden (analojiden) kaynaklanan bir hatadır; gerçek evrimsel soy hattını (filogeniyi) yalnızca ortak atadan miras alınan homolog özellikler ve moleküler diziler doğru gösterir.'),
  ('Aynı nehir sisteminde yaşayan iki alabalık popülasyonundan biri göl kıyısındaki çakıllı yataklarda sonbaharda, diğeri ise göle dökülen akarsu kollarında ilkbaharda yumurta bırakmaktadır. Bu iki popülasyon arasında gen akışını engelleyen mekanizmalar birlikte düşünüldüğünde aşağıdakilerden hangisi doğrudur?', 'Hem habitat (üreme alanı) yalıtımı hem de mevsimsel (zamansal) yalıtım bir arada zigot öncesi engel oluşturmaktadır', ['Yalnızca zigot sonrası F2 melez bozulması iki popülasyonun karışmasını önlemektedir', 'Balıkların kromozom sayıları farklı olduğu için aralarında mekanik kabuk engeli vardır', 'Akarsu ve göl arasında bin metrelik şelale bulunduğu için gametik reseptör yalıtımı vardır'], 'Biri göl kıyısında diğeri akarsuda ürediği için habitat yalıtımı, biri sonbaharda diğeri ilkbaharda ürediği için mevsimsel yalıtım söz konusudur; doğada çoğu zaman birden fazla zigot öncesi engel birlikte çalışır.'),
  ('Bir bitki ekoloğu, diploit (2n=18) bir yabani ot popülasyonunun yayılış haritasını çıkarırken yüksek rakımlı ve sert iklimli dağ yamaçlarında aynı cinse ait tetraploit (4n=36) yeni bir türün baskın olduğunu, bu iki formun sınır bölgesinde ise doğada hiç verimli tohum oluşturan ara melez bulunmadığını saptamıştır. Bu durumla ilgili en kapsamlı bilimsel çıkarım hangisidir?', 'Kromozom katlanması (poliploidi) hem ata türle anında zigot sonrası üreme yalıtımı sağlamış hem de artan gen kopya sayısıyla ekstrem koşullara uyumu kolaylaştırmıştır', ['Yüksek rakımdaki düşük oksijen basıncı bitkilerin yaprak hücrelerinde mayoz bölünmeyi durdurarak geçici bir modifikasyon yaratmıştır', 'Tetraploit ve diploit bitkiler arasında hiçbir genetik akrabalık olmayıp yakınsak evrimle aynı familyada sınıflandırılmışlardır', 'Sınır bölgesindeki bitkiler yalnızca davranışsal kur dansları uyuşmadığı için birbirine polen gönderememektedir'], 'Poliploid bitkiler ata diploitlerle çaprazlandığında kısır triploit (3n=27) döller oluştuğu için güçlü üreme yalıtımı kurulur; ayrıca fazladan gen kopyaları yeni işlevler kazanarak zorlu çevre koşullarına (soğuk, kuraklık) toleransı sıkça artırır.'),
  ('Büyük Karayip adalarının (Küba, Hispaniola, Jamaika, Porto Riko) her birinde birbirinden bağımsız olarak "taç-dal", "gövde-zemin" ve "çimen-çalı" uzmanı olan Anolis kertenkelesi ekomorflarının evrimleştiği, her adadaki farklı ekomorfların ise kendi adasındaki türlerle diğer adalardaki ikizlerinden daha yakın akraba olduğu bulunmuştur. Bu ünlü doğa deneyi neyi kanıtlar?', 'Benzer ada ekosistemlerinde doğal seçilimin uyumsal açılımı öngörülebilir biçimde tekrarlayarak yakınsak ekomorflar ürettiğini', ['Evrimin tamamen tesadüfi olduğu için hiçbir zaman iki farklı yerde benzer bir vücut formu üretemeyeceğini', 'Kertenkelelerin her fırtınada adalar arasında yüzerek yalnızca kendi ekomorflarıyla çiftleştiğini', 'Adalardaki kertenkele çeşitliliğinin doğal seçilim olmadan yalnızca poliploidi mutasyonlarıyla ortaya çıktığını'], 'Jonathan Losos\'un araştırmalarıyla belgelenen Karayip Anolis kertenkeleleri; her adada bağımsız uyumsal açılım (ıraksak evrim) yaşanırken, adalar arasında benzer mikrohabitatların tıpatıp aynı vücut tiplerini (yakınsak evrimi) tekrar tekrar ortaya çıkardığını kanıtlar.'),
  ('Bir dağ vadisinde yaşayan iki yakın akraba çalı türü (A ve B) nadiren melezlenmektedir. Doğal ortamda A türü kurak kayalıklarda, B türü sulak dere kenarında yaşarken oluşan nadir F1 melezler ne kuraklığa A kadar dayanabilmekte ne de sulak alanda B kadar hızlı büyüyebilmektedir. Bu durum ekolojik açıdan ne tip bir üreme engeli yaratır?', 'Melezlerin her iki ata nişinde de düşük uyum gücüne sahip olmasına dayalı ekolojik zigot sonrası yalıtım', ['Polen ve yumurtanın çekirdeklerinin kaynaşmasını önleyen zigot öncesi gametik yalıtım', 'Çiçeklerin yalnızca gece yarısı açılmasına dayalı zigot öncesi zamansal yalıtım', 'Kromozom sayısının dört katına çıkmasıyla oluşan otopoliploidik türleşme'], 'Melez birey genetik olarak yaşayabilir ve laboratuvarda doğurgan olsa bile doğada her iki ebeveynin özel nişine de uyumsuz (ara form dezavantajı) olduğu için elenir; bu durum dışsal/ekolojik zigot sonrası yalıtımdır.'),
  ('Evrimsel kanıtlar bütüncül olarak değerlendirildiğinde; karşılaştırmalı anatomi, embriyoloji, biyocoğrafya, paleontoloji ve moleküler biyoloji verilerinin birbirinden bağımsız yöntemlerle çalışmasına rağmen aynı evrimsel soyağaçlarını doğrulaması bilim felsefesi açısından ne ifade eder?', 'Farklı bilim dallarından gelen bağımsız kanıt hatlarının aynı kuramı doğrulayarak evrimsel açıklamanın güvenilirliğini en üst düzeye çıkardığını', ['Moleküler biyoloji geliştiği için fosil ve anatomi araştırmalarının tamamen geçersiz sayılması gerektiğini', 'Tüm canlı türlerinin sabit kalarak hiçbir çevresel seçilim baskısına yanıt vermediğini', 'Yalnızca gözle görülebilen iri memeli hayvanların evrimsel süreçlere dahil olduğunu'], 'Fosil yaşları, kıta hareketleri, embriyonik gelişim evreleri, körelmiş/homolog organlar ve DNA dizilimlerinin birbiriyle tutarlı aynı dallanma örüntüsünü vermesi (kanıtların yakınsaması / consilience), evrim kuramının en güçlü bilimsel dayanağıdır.'),
  ('Doğal seçilim açısından dezavantajlı görünen (avcılara yerini belli eden ve yüksek enerji harcatan) abartılı erkek süslerinin eşeysel seçilimle evrimleşmesini açıklayan "handikap (engel) ilkesi" neyi savunur?', 'Bu kadar ağır bir maliyete rağmen hayatta kalabilen bir erkeğin yüksek genetik kaliteye ve dirençli bağışıklığa sahip olduğunu dişiye dürüstçe kanıtladığını', ['Dişilerin görme duyusu zayıf olduğu için abartılı süslerin aslında erkekleri yırtıcılara karşı tamamen görünmez kıldığını', 'Gösterişli erkeklerin üreme yeteneğinin olmadığını ve popülasyonu korumak için kendilerini yırtıcılara feda ettiğini', 'Eşeysel seçilimin genlerle hiçbir ilgisi olmayıp yalnızca yaşlı bireylerde görülen çevresel bir modifikasyon olduğunu'], 'Amotz Zahavi\'nin handikap ilkesine göre yüksek maliyetli süsleri taşıyıp sağ kalabilmek "iyi genlerin" taklit edilemez dürüst bir sinyalidir; dişiler bu erkekleri seçerek yavrularına kaliteli genler aktarır.'),
  ('Pasifik somonlarında (Oncorhynchus kisutch) üreme alanlarında büyük gövdeli "kanca burunlu" erkeklerin birbirleriyle dövüşerek dişilere ulaştığı, çok küçük gövdeli "jack" erkeklerin ise kayaların arasından gizlice süzülerek yumurtaları döllediği; orta boylu erkeklerin ise ne dövüş kazanabildiği ne de gizlenebildiği gözlenmiştir. Bu durum erkek vücut boyu üzerinde nasıl bir etki yaratır?', 'Dallandırıcı seçilimle erkek popülasyonunda hem çok küçük hem çok büyük boy stratejilerinin bir arada korunmasını sağlar', ['Dengeleyici seçilimle birkaç kuşak içinde tüm erkek somonların orta boyda sabitlenmesine neden olur', 'Yönlü seçilimle küçük boylu erkeklerin gen havuzundan tamamen silinip yalnız dev bireylerin kalmasına yol açar', 'Dişi somonların yumurta bırakmayı tamamen durdurarak eşeysiz üremeye geçmesini zorunlu kılar'], 'Üreme başarısında iki zıt uç strateji (dövüşçü büyükler ve sinsi küçükler) başarılı olurken ara boydakiler başarısız olduğundan, eşeysel rekabet dallandırıcı seçilim biçiminde işler.'),
  ('Charles Darwin *Türlerin Kökeni* kitabının hemen ilk bölümünü güvercin yetiştiriciliği ve evcil hayvan ıslahına (yapay seçilime) ayırmıştır. Darwin\'in kuramını anlatırken yapay seçilimden yola çıkmasının temel bilimsel gerekçesi nedir?', 'İnsan seçimiyle kısa sürede gözlemlenebilen büyük kalıtsal değişimlerin, doğadaki seçilimle jeolojik zamanlarda çok daha büyük evrimsel dönüşümler yaratabileceğine somut bir model oluşturması', ['Doğadaki tüm vahşi canlı türlerinin aslında geçmiş uygarlıklar tarafından yapay seçilimle çiftliklerde üretilip doğaya salındığını kanıtlamak istemesi', 'Yapay seçilimin mutasyonlara ihtiyaç duymadan yalnızca çevresel modifikasyonları gelecek kuşaklara aktarabildiğini göstermek istemesi', 'Doğal seçilimin yalnız tek hücreli canlılarda, yapay seçilimin ise yalnız kuş ve memelilerde çalıştığını ortaya koymak istemesi'], 'Darwin, çiftçilerin ve yetiştiricilerin küçük kalıtsal farkları seçerek birkaç kuşakta ne kadar farklı ırklar üretebildiğini (yapay seçilim) göstererek, doğada yaşam mücadelesinin milyonlarca yılda neler başarabileceğini (doğal seçilim) ikna edici bir analojiyle açıklamıştır.'),
  ('Tarım ve hayvancılıkta yüksek süt verimi veya tek tip iri meyve elde etmek amacıyla çok dar bir damızlık grubuyla yoğun yapay seçilim ve akraba içi çiftleştirme yapılmasının yarattığı en ciddi genetik risk nedir?', 'Gen havuzunun daralmasıyla zararlı çekinik alellerin homozigotlaşması ve salgın hastalıklara karşı tüm popülasyonun savunmasız kalması', ['Seçilen bireylerde kromozom sayısının her kuşakta yarıya düşerek türün tek hücreli forma geri dönmesi', 'Yapay seçilim uygulanan canlılarda mitoz bölünme hızının sıfırlanarak büyümenin tamamen durması', 'Evcil ırkların yabani atalarından daha fazla genetik çeşitlilik kazanarak kontrolsüzce istilacı türe dönüşmesi'], 'Yoğun yapay seçilim istenen özelliği sabitlerken genetik varyasyonu ciddi biçimde aşındırır; homozigotluk artışı kalıtsal kusurları (inbreeding depresyonu) ve yeni patojenlere toplu duyarlılığı beraberinde getirir.'),
  ('Erkek lepistes balıklarında (Poecilia reticulata) yırtıcı balıkların çok yoğun olduğu akarsu kollarında soluk ve küçük benekli erkeklerin, yırtıcıların bulunmadığı üst su kollarında ise çok parlak turuncu-mavi benekli erkeklerin baskın olması nasıl açıklanır?', 'Yırtıcı varlığında hayatta kalmaya dayalı doğal seçilimin, yırtıcı yokluğunda ise dişi tercihine dayalı eşeysel seçilimin baskın gelmesiyle', ['Üst su kollarındaki güneş ışığının balık pullarını turuncuya boyayan kalıtsal olmayan bir modifikasyon yapmasıyla', 'Yırtıcı balıkların yalnızca soluk renkli lepistesleri avlayıp parlak renkli olanlardan korkup kaçmasıyla', 'Lepisteslerde renk desenlerinin genetik olmayıp yenilen yosun türlerine göre her gün değişmesiyle'], 'John Endler\'in ünlü lepistes deneyleri, doğal seçilim (avcılardan gizlenme) ile eşeysel seçilim (dişileri cezbetme) arasındaki karşıt dengeyi gösterir; avcı kalktığında eşeysel seçilim parlaklığı hızla artırır.'),
  ('Süt sığırlarında (örneğin Holstein ırkı) yalnız en yüksek süt verimine göre onlarca yıl uygulanan yoğun yapay seçilim sonucunda ineklerde topallık, meme enfeksiyonu (mastitis) ve döl verimi düşüklüğü gibi sorunların artması evrimsel açıdan neyi gösterir?', 'Tek bir özelliğe aşırı odaklanan yapay seçilimin enerji bütçesini ve genetik dengeyi bozarak canlının genel biyolojik uyumunu düşürebildiğini', ['Yüksek süt üretiminin sığırların kromozomlarını parçalayarak bulaşıcı bakterileri hücre içinde yoktan var ettiğini', 'Yapay seçilim uygulanan hayvanlarda doğal fizyolojik sınırların tamamen ortadan kalkarak sonsuz verime ulaşılabileceğini', 'Süt verimi genlerinin yalnız erkek bireylerdeki Y kromozomu üzerinde taşındığını ve dişilere geçemediğini'], 'Organizmanın metabolik kaynakları sınırlıdır (evrimsel ödünleşim / trade-off); tüm enerjinin süt üretimine yönlendirilmesi ve dar genetik havuz, bağışıklık ve üreme sağlığından ödün verilmesine yol açar.'),
  ('Cennet dulavratotu kuşlarında (Vidua paradisaea) araştırmacılar bazı erkeklerin kuyruk tüylerini makasla kesip kısaltmış, kestikleri parçaları diğer erkeklerin kuyruklarına yapıştırarak normalden daha uzun hale getirmiş ve kuyruğu uzatılan erkeklerin çok daha fazla dişiyle çiftleştiğini saptamıştır. Bu deney neyi doğrudan kanıtlar?', 'Dişilerin çiftleşme kararında erkeklerin kuyruk uzunluğunu aktif bir eşeysel seçilim ölçütü olarak kullandığını', ['Yapıştırılan tüylerin erkek kuşların üreme hücrelerindeki DNA dizilimini değiştirerek yavrulara uzun kuyruk geçirdiğini', 'Kuyruğu kesilen erkeklerin yırtıcılardan kaçamadığı için deneyin ilk gününde tamamının avlanarak öldüğünü', 'Kuyruk uzunluğunun doğada hiçbir üst sınırı olmadığını ve metrelerce uzamasının uçuşu kolaylaştırdığını'], 'Malte Andersson\'ın bu klasik manipülasyon deneyi, dişi tercihinin (interseksüel seçilim) abartılı kuyruk uzunluğunu doğrudan ödüllendirdiğini deneysel olarak kanıtlamıştır.'),
  ('Afrika\'daki Viktorya Gölü\'nde yaşayan çiklit (Cichlidae) balıklarında suyun yüzeyine yakın mavi ışığın baskın olduğu yerlerde mavi renkli erkeklerin, daha derin ve kırmızı ışığın ulaştığı sularda ise kırmızı renkli erkeklerin dişilerce seçildiği; ancak insan kaynaklı kirlilik yüzünden su bulanıklaşınca dişilerin renkleri ayırt edemeyip türler arası melezleşmenin başladığı görülmüştür. Bu bulgu neyi gösterir?', 'Dallandırıcı eşeysel seçilimin sürdürdüğü üreme yalıtımının çevresel sinyal ortamı bozulduğunda ortadan kalkabildiğini', ['Bulanık suyun balıkların pullarındaki pigment genlerini silerek tüm balıkları renksiz albinolara dönüştürdüğünü', 'Mavi ve kırmızı çiklit balıklarının başlangıçtan beri kromozom sayıları farklı olduğu için kısır yavrular verdiğini', 'Su kirliliğinin balıklarda yapay seçilim başlatarak göldeki tür sayısını iki katına çıkardığını'], 'Farklı derinliklerdeki ışık spektrumuna uyum sağlayan duyusal eğilim ve dişi tercihi (dallandırıcı eşeysel seçilim) türleri ayrı tutarken, bulanıklık görsel seçimi bozup genetik sınırları eritmiştir.'),
  ('Böceklerde bazı erkeklerin çiftleşme sonrasında dişinin başka erkeklerle çiftleşmesini önleyen tıkaçlar bırakması veya dişiyi rakiplerden fiziksel olarak beklemesi, dişilerin ise birden fazla erkekle çiftleşip istenmeyen spermleri dışarı atacak anatomik yapılar geliştirmesi nasıl tanımlanır?', 'Erkek ve dişi üreme çıkarlarının çatışmasından doğan eşeysel birlikte evrim', ['Türün neslini hızla tüketmeye yönelik ölümcül ve uyumsuz somatik mutasyonlar dizisi', 'Doğal seçilimin üreme organları üzerinde hiçbir etkisinin olmadığının deneysel kanıtı', 'İnsanların zararlı böcekleri kısırlaştırmak için laboratuvarda uyguladığı yapay seçilim'], 'Eşeysel seçilimde erkek ve dişinin optimum üreme stratejileri her zaman örtüşmez; bir eşeydeki manipülatif adaptasyon diğer eşeyde karşı-adaptasyonu tetikler (seksüel çatışma).'),
  ('Bulldog ve Pug gibi aşırı basık yüzlü (brakisefalik) köpek ırklarının ciddi solunum güçlüğü çekmesi ve çoğunun kalça-kafa uyumsuzluğu nedeniyle sezaryen olmadan doğuramaması evrimsel biyoloji açısından nasıl yorumlanmalıdır?', 'İnsanların estetik beğenisine dayalı yapay seçilimin, doğada hızla elenecek kadar düşük uyum başarısına sahip fenotipleri sürdürebildiğinin kanıtıdır', ['Doğal seçilimin evcil köpekleri vahşi kurtlara göre solunum ve doğum açısından çok daha üstün hale getirdiğinin göstergesidir', 'Köpeklerin ev ortamında hareketsiz kalması sonucu burun kemiklerinin kullanılmadığı için modifikasyonla kısaldığının sonucudur', 'Dengeleyici seçilimin tüm memeli türlerinde kafa iskeletini küresel bir şekle sokma eğiliminin doğal bir yansımasıdır'], 'Vahşi doğada nefes alamayan ve normal doğum yapamayan bir varyant doğal seçilimle derhal elenir; bu özelliklerin kalıcılığı tamamen insan müdahalesi ve yapay seçilim sayesindedir.'),
  ('Ronald Fisher\'ın "kontrolden çıkmış (runaway) eşeysel seçilim" modeline göre, başlangıçta hafifçe uzun kuyruklu erkeklerin tercih edildiği bir kuş popülasyonunda kuyruk uzunluğunun kuşaklar içinde hızla abartılı boyutlara ulaşmasının genetik mekanizması nedir?', 'Erkeklerdeki uzun kuyruk alelleri ile dişilerdeki uzun kuyruk tercihi alellerinin ortak yavrularda birlikte kalıtılarak birbirini pozitif geri bildirimle güçlendirmesi', ['Erkek kuşların kuyruk tüylerini gagalarıyla her gün çekiştirerek uzatması ve bu kazanılmış özelliği yavrularına aktarması', 'Doğal seçilimin yırtıcılardan kaçmayı imkansız hale getirene kadar tüm kuşlarda kuyruk uzamasını zorunlu kılması', 'Dişi kuşların yalnız kuyruksuz erkeklerle çiftleşmesine rağmen mutasyonların her kuşakta kuyruğu iki kat uzatması'], 'Dişi tercihi geni ile erkek süsü geni çiftleşmeler sonucu yavrularda genetik olarak eşleşir (bağlantı dengesizliği); özellik yayıldıkça tercih de güçlenir ve doğal seçilim (avcılık/enerji) frenleyene dek sürer.'),
  ('Koyun sürülerinde yün verimini artırmak için sürekli yapağısı en gür bireyleri seçen bir yetiştirici (yapay seçilim) ile aynı sürünün kurak ve aşırı sıcak bir bozkıra terk edilerek insan bakımından çıkması (doğal seçilim) durumlarında yapağı kalınlığının yönü sırasıyla nasıl değişir?', 'Yapay seçilimde kalın yapağı yönünde artarken, sıcak doğaya terk edildiğinde ısı stresi nedeniyle ince yapağı yönünde yönlü doğal seçilimle azalır', ['Her iki durumda da kalın yapağı güneş ışınlarını kestiği için sınırsız biçimde artmaya devam eder', 'Yapay seçilimde yapağı tamamen dökülürken, sıcak bozkırda kutup iklimine hazırlık için kalınlaşır', 'Koyunlar evcilleştirildiği için gen havuzları donmuştur ve doğaya bırakılsalar bile hiçbir seçilim işlemez'], 'İnsan varken ekonomik değer (kalın yün) seçilir; insan çekildiğinde aşırı kalın yün sıcak çarpmasına ve parazitlere yol açtığından doğal seçilim yönü tersine çevirir (feral/yabanileşme uyumu).'),
  ('Kuzey Amerika\'daki kaya güvercinlerinden türetilen evcil güvercin ırkları (taklacı, balon kursaklı, yelpaze kuyruklu) kendi aralarında çiftleştirildiğinde birkaç kuşak sonra doğan yavruların yeniden gri-mavi kanat çizgili yabani kaya güvercini görünümüne (atasal fenotipe) dönme eğilimi göstermesi neyi kanıtlar?', 'Farklı evcil ırkların ortak bir yabani atadan yapay seçilimle türediğini ve melezlenmeyle atasal gen kombinasyonlarının yeniden bir araya geldiğini', ['Evcil güvercin ırklarının her birinin farklı yırtıcı kuş ailelerinden bağımsız olarak evrimleştiğini', 'Güvercinlerde tüy rengi ve kuyruk şeklinin genlerle değil kafesin büyüklüğüyle belirlendiğini', 'Atasal kaya güvercini genlerinin tüm evcil ırklarda mutasyonla tamamen yok edildiğini'], 'Darwin\'in bizzat yaptığı güvercin çaprazlama deneylerinde gözlemlediği bu "atavizm / atasal forma dönüş", tüm uç ırkların *Columba livia* türünden yapay seçilimle ayrıldığının güçlü genetik kanıtıdır.'),
  ('Afrika fillerinde fildişi ticareti nedeniyle kaçak avcıların on yıllar boyunca hep en büyük fildişli bireyleri vurması sonucunda, bazı milli parklarda doğuştan fildişsiz (dişsiz) doğan dişi fil oranının %2\'den %30\'un üzerine çıkması hangi kavramla en doğru tanımlanır?', 'İnsan kaynaklı seçici avcılığın tetiklediği hızlı ve istenmeyen yönlü seçilim', ['Fillerin avcılardan korunmak için dişlerini kayalara sürterek kırmasıyla oluşan modifikasyon', 'Milli park görevlilerinin süs amacıyla dişsiz filleri çiftleştirdiği planlı yapay seçilim', 'Dişsiz fillerin erkek filler tarafından daha çok beğenilmesine dayalı eşeysel seçilim'], 'Kaçak avcılık (yapay seçilim gibi planlı bir ıslah olmasa da) insan eliyle oluşturulan çok sert bir seçilim baskısıdır; fildişi geliştirmeyen mutant bireyler vurulmaktan kurtulup genlerini hızla yaymıştır.'),
  ('Bir gül yetiştiricisi bahçesindeki soluk pembe güllerden her kuşakta en koyu pembe olanları seçip çaprazlayarak on kuşak sonunda koyu kırmızı güller elde etmiştir; ancak yirminci kuşaktan sonra ne kadar seçilim yaparsa yapsın rengin daha fazla koyulaşmadığını (seçilim platosuna ulaştığını) görmüştür. Bunun en olası genetik nedeni nedir?', 'Başlangıçtaki gen havuzunda bulunan renk koyulaştırıcı mevcut alel varyasyonunun tükenip homozigotlaşması', ['Yirminci kuşaktan itibaren gül bitkilerinde fotosentez ve solunum olaylarının tamamen durması', 'Yapay seçilimin yirmi kuşak sonra kendiliğinden dengeleyici doğal seçilime dönüşmesi', 'Gül taç yapraklarının güneş ışığını soğurma kapasitesinin mutasyonları geri çevirmesi'], 'Yapay veya yönlü seçilim mevcut kalıtsal varyasyonu kullanır; ilgili lokuslardaki tüm koyu renk alelleri %100 frekansa ulaşıp sabitlendiğinde, yeni bir mutasyon ortaya çıkana dek seçilim yanıtı durur.'),
  ('Büyük boynuzlu yaban koyunlarında (Ovis canadensis) trofe avcılarının on yıllar boyunca yalnızca en büyük ve kıvrımlı boynuza sahip baskın koçları vurması sonucunda popülasyondaki koçların ortalama boynuz büyüklüğünün %25 küçüldüğü saptanmıştır. Burada doğal ortamda işleyen eşeysel seçilim ile insan avcılığı nasıl bir etkileşim içindedir?', 'Eşeysel seçilim büyük boynuzlu koçları çiftleşmede kayırırken, trofe avcılığı bu koçları üreyemeden ortadan kaldırarak ters yönde güçlü bir seçilim uygulamıştır', ['Trofe avcılığı ve eşeysel seçilim aynı yönde etki ederek boynuzsuz dişilerin tamamının elenmesine yol açmıştır', 'Avcıların tüfek sesleri koçların boynuz büyüme hormonunu baskılayarak kalıtsal olmayan bir küçülme yaratmıştır', 'Büyük boynuzlu koçlar vurulduğunda küçük boynuzlu koçlar bir gecede boynuzlarını uzatarak yerlerini almıştır'], 'Normalde eşey içi rekabet büyük boynuzu seçer; ancak avcılar en başarılı damızlık adaylarını sistematik olarak vurduğunda küçük boynuzlu erkekler üreme fırsatı bularak gen frekanslarını artırmıştır.'),
  ('Gümüş tilkiler (Vulpes vulpes) üzerinde Dmitri Belyaev tarafından başlatılan ünlü evcilleştirme deneyinde, araştırmacılar tilkileri yalnızca "insandan kaçmama ve uysallık" davranışına göre kırk kuşak boyunca yapay seçilime tabi tutmuş; ancak seçmedikleri halde tilkilerde sarkık kulaklar, kıvrık kuyruk ve alacalı kürk gibi köpeksi fiziksel özelliklerin de kendiliğinden ortaya çıktığını görmüştür. Bunun nedeni nedir?', 'Uysallığı sağlayan böbreküstü bezi ve nöral krest hücrelerindeki genetik değişimlerin pigmentasyon ve kıkırdak gelişimini de etkileyen çok yönlü (pleiotropik) etkiye sahip olması', ['Kafeste yaşayan tilkilerin köpekleri görerek onlara benzemek için kulak kaslarını bilinçli olarak gevşetmesi', 'Soğuk Sibirya ikliminin yalnız uysal tilkilerde kürk rengini değiştiren kalıtsal olmayan modifikasyon yapması', 'Deney sırasında tilkilere köpek kanı enjekte edilerek yatay gen transferi gerçekleştirilmiş olması'], 'Belyaev\'in deneyi "evcilleştirme sendromu"nu aydınlatmıştır: Davranışsal uysallık için yapılan yapay seçilim, embriyonik nöral krest hücre göçünü değiştirerek kıkırdak, diş ve pigment özelliklerini de birlikte sürükler.'),
  ('Tarımda tek bir yüksek verimli buğday veya patates klonunun tüm ülke tarlalarına ekilmesi (monokültür ve aşırı yapay seçilim), 1840\'lardaki İrlanda Patates Kıtlığı örneğinde olduğu gibi neden büyük bir ekolojik felaket riski taşır?', 'Genetik varyasyon sıfıra yakın olduğu için tek bir patojen mantar veya virüs evrimleştiğinde tüm ürünün direnç gösteremeden aynı anda çökmesine yol açar', ['Yapay seçilimle elde edilen bitkiler topraktaki tüm oksijeni bir yılda tüketerek tarlayı kalıcı çöle dönüştürür', 'Tek tip ekilen patatesler bir kuşak sonra kendi aralarında dallandırıcı seçilim geçirerek zehirli yabani otlara dönüşür', 'Klon bitkilerde mitoz bölünme hızı çok yüksek olduğu için yumrularda besin değeri hiç kalmaz'], 'Doğal popülasyonları salgınlardan koruyan sigorta genetik varyasyondur; yapay seçilimle tek bir genotip (monokültür) yaygınlaştırıldığında patojene karşı direnç aleli taşıyan birey bulunmaz.'),
  ('Deniz iğnelerinde yapılan bir araştırmada erkeklerin daha iri ve parlak dişilerle çiftleştiğinde kuluçka keselerindeki embriyolara daha fazla besin ve oksijen aktardığı, küçük ve soluk dişilerle çiftleştiğinde ise embriyo bakımını azalttığı saptanmıştır. Bu olgu eşeysel seçilimde neyi gösterir?', 'Bireylerin eş kalitesine bağlı olarak yavruya yapacakları ebeveyn yatırımını ayarlayarak üreme başarısını optimize edebildiğini', ['Küçük dişilerin bıraktığı yumurtaların tamamının döllenmemiş ve kromozomsuz hücreler olduğunu', 'Deniz iğnelerinde yavru bakımının tamamen çevresel su sıcaklığına bağlı kalıtsal olmayan bir refleks olduğunu', 'Dengeleyici seçilimin iri dişilerin üreme başarısını her zaman sıfıra indirdiğini'], 'Eşeysel seçilim yalnızca çiftleşme öncesinde bitmez; çiftleşme sonrasında da kaliteli eşten olan yavrulara daha fazla yatırım yapılması (kriptik seçim ve diferansiyel yatırım) evrimsel bir stratejidir.'),
  ('Geyik böceklerinde (Lucanus cervus) dev çeneli (mandibulalı) erkekler ağaç özsuyu sızıntılarını savunup rakiplerini ağaçtan atarken, besin azlığı nedeniyle küçük kalan larvalardan çıkan küçük çeneli erkekler uçma yetenekleri daha çevik olduğu için sızıntılara daha erken ulaşıp dişileri bulabilmektedir. Bu durumla ilgili hangisi söylenebilir?', 'Hem beslenmeye bağlı gelişimsel esneklik hem de alternatif eş bulma taktikleri popülasyonda farklı erkek morfolojilerinin sürmesini sağlar', ['Küçük çeneli erkek geyik böcekleri tamamen farklı bir böcek türünün bireyleri olup büyüklerle aynı gen havuzunu paylaşmaz', 'Dev çeneler geyik böceklerinin ağaç gövdelerini kesip yemek için kullandığı sindirim organlarıdır', 'Dengeleyici seçilim tüm erkek geyik böceklerinin çene boyunu milimetrik olarak eşit tutmaktadır'], 'Birçok boynuzlu/çeneli böcekte larva dönemindeki beslenme düzeyi eşik bir gelişim şalterini tetikler ve eşeysel seçilim baskısı altında iki farklı morfolojik/davranışsal üreme taktiği birlikte işler.'),
  ('"Yapay seçilim yeni genler yaratmaz, ancak doğal popülasyonlarda çok nadir görülen fenotiplerin frekansını hızla artırıp yeni alel kombinasyonlarını bir araya getirir." ifadesi genetik açıdan doğru mudur?', 'Doğrudur; yapay seçilim kendiliğinden oluşan rastgele mutasyonları ve rekombinasyonları seçerek nadir özellikleri görünür ve yaygın hale getirir', ['Yanlıştır; yapay seçilim uygulayan yetiştiricinin zihinsel isteği hayvanların üreme hücrelerinde doğrudan hedefe yönelik mutasyon yaratır', 'Doğrudur; çünkü yapay seçilim yapılan canlılarda DNA replikasyonu ve mayoz bölünme olayları tamamen durmaktadır', 'Yanlıştır; yapay seçilim yalnızca çevresel modifikasyonları biriktirdiği için gen frekanslarında hiçbir değişikliğe yol açmaz'], 'Tıpkı doğal seçilim gibi yapay seçilim de mutasyon üretmez; zaten var olan veya üreme sürecinde rastgele beliren kalıtsal varyasyonları seçip melezleyerek uç kombinasyonlar oluşturur.'),
  ('Deniz kabuklularından olan meşe palamudu midyeleri kayalara yapışık (sesil) yaşar; ancak kendi boylarının sekiz katına ulaşabilen (hayvanlar aleminin vücut oranına göre en uzun) eşey organlarına sahip olmaları, hareketsiz yaşam biçiminde hangi seçilim baskısıyla evrimleşmiştir?', 'Hareketsiz bireylerin dalgalı suda komşu bireylere ulaşıp döllenme başarısını artırma yönündeki eşeysel seçilim rekabetiyle', ['Kayalardaki kalsiyum karbonat minerallerinin kabuk içindeki dokuları uzatan modifikasyon etkisiyle', 'Balıkçıların daha uzun uzuvlu kaya midyelerini yemek için seçtiği yapay seçilim uygulamasıyla', 'Dengeleyici seçilimin tüm deniz omurgasızlarında iç döllenmeyi yasaklamasıyla'], 'Yer değiştiremeyen (sesil) ama iç döllenme yapan hermafrodit kaya midyelerinde daha uzağa erişebilmek, daha fazla komşuyu dölleyebilmek demektir; bu da güçlü bir eşeysel seçilim doğurmuştur.'),
  ('Kuşlarda ve memelilerde birçok türde dişilerin bağışıklık sistemini yöneten MHC (doku uygunluk kompleksi) genleri bakımından kendilerinden "en farklı" kokuya sahip erkekleri çiftleşmek için tercih ettiği saptanmıştır. Bu eş seçimi stratejisinin evrimsel avantajı nedir?', 'Doğan yavruların MHC genleri bakımından yüksek heterozigotluğa sahip olarak çok daha geniş çeşitlilikte patojeni tanıyıp direnç göstermesini sağlamak', ['Yavruların anne ve babadan tamamen farklı bir kromozom sayısına sahip olarak yeni bir tür başlatmasını sağlamak', 'Aynı sürüdeki tüm bireylerin genetik olarak tek yumurta ikizi kadar özdeş hale gelmesini hızlandırmak', 'Koku alma duyusunun zamanla körelerek görsel eş seçiminin tamamen ortadan kalkmasına zemin hazırlamak'], 'MHC bağımlı eş seçimi hem akraba evliliğini (inbreeding) önler hem de yavrulara daha geniş spektrumlu bir bağışıklık repertuvarı kazandırarak hayatta kalma başarısını yükseltir.'),
  ('Modern tıp, tarım ve hayvancılık uygulamaları dikkate alındığında aşağıdakilerden hangisi insan faaliyetlerinin canlıların evrimini hem "planlı yapay seçilim" hem de "plansız seçici baskı" yoluyla yönlendirdiğini birlikte gösteren doğru bir eşleştirmedir?', 'Yüksek verimli süt sığırı ıslahı planlı yapay seçilim; aşırı antibiyotik kullanımıyla dirençli bakteri gelişimi ise plansız yönlü seçilimdir', ['Antibiyotik dirençli bakterilerin üretilmesi planlı yapay seçilim; buğday ıslahı ise tamamen rastgele genetik sürüklenmedir', 'Köpek ırklarının elde edilmesi çevresel modifikasyon; güvelerdeki sanayi melanizmi ise insan eliyle yapılan planlı ıslah çalışmasıdır', 'Herbisit dirençli yabani otların çoğalması dengeleyici seçilim; çekirdeksiz üzüm üretimi ise eşeyler arası eşeysel seçilimdir'], 'İnsanlar istedikleri özellikleri üretirken planlı yapay seçilim uygular; ilaç, pestisit, kirlilik ve avcılıkla ise istemeden de olsa çok güçlü yönlü doğal/insan kaynaklı seçilim baskıları yaratır.'),
  ('Doğal seçilimin üç ana modunu (yönlü, dengeleyici, dallandırıcı) popülasyon ortalaması ve varyansı üzerindeki etkileri bakımından karşılaştıran aşağıdaki ifadelerden hangisi tamamen doğrudur?', 'Yönlü seçilim ortalamayı bir uca kaydırır; dengeleyici seçilim ortalamayı koruyup varyansı daraltır; dallandırıcı seçilim ise uçları kayırarak varyansı genişletir', ['Yönlü seçilim varyansı iki katına çıkarır; dengeleyici seçilim ortalamayı sürekli değiştirir; dallandırıcı seçilim ise tüm bireyleri tek tipte eşitler', 'Üç seçilim türü de popülasyonun aritmetik ortalamasını sabit tutarken yalnızca mutasyon hızını farklı yönlerde değiştirir', 'Dengeleyici seçilim çift tepeli grafik oluştururken, dallandırıcı seçilim her zaman tek tepeli dar bir çan eğrisi üretir'], 'İstatistiksel genetik açısından yönlü seçilim ortalamayı (mean) ötelemekte, dengeleyici seçilim dağılımı (variance) küçültüp ortalamayı sabitlemekte, dallandırıcı seçilim ise varyansı büyütüp bimodalite yaratmaktadır.'),
];
